"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { ArrowLeft, TrendingUp, Eye, Users, MessageSquare, FileText } from "lucide-react";

interface AnalyticsData {
    totalPosts: number;
    totalUsers: number;
    totalComments: number;
    popularPosts: Array<{
        slug: string;
        title: string;
        category: string;
    }>;
}

export default function AnalyticsPage() {
    const [data, setData] = useState<AnalyticsData | null>(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchAnalytics();
    }, []);

    const fetchAnalytics = async () => {
        try {
            const response = await fetch("/api/admin/analytics");
            const analyticsData = await response.json();
            setData(analyticsData);
        } catch (error) {
            console.error("Failed to fetch analytics:", error);
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="container px-4 md:px-6 py-12">
                <div className="flex items-center justify-center min-h-[400px]">
                    <div className="text-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
                        <p className="text-muted-foreground">Loading analytics...</p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container px-4 md:px-6 py-8 md:py-12">
            {/* Header */}
            <div className="mb-8">
                <div className="flex items-center gap-2 mb-2">
                    <Button variant="ghost" size="sm" asChild>
                        <Link href="/admin">
                            <ArrowLeft className="h-4 w-4 mr-2" />
                            Back to Dashboard
                        </Link>
                    </Button>
                </div>
                <h1 className="text-3xl md:text-4xl font-bold tracking-tight">Analytics</h1>
                <p className="text-muted-foreground mt-2">View your blog statistics and insights</p>
            </div>

            {/* Statistics Overview */}
            <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4 mb-8">
                <Card className="hover-lift">
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Posts</CardTitle>
                        <FileText className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data?.totalPosts || 0}</div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Published articles
                        </p>
                    </CardContent>
                </Card>

                <Card className="hover-lift">
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Total Users</CardTitle>
                        <Users className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data?.totalUsers || 0}</div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Registered users
                        </p>
                    </CardContent>
                </Card>

                <Card className="hover-lift">
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Comments</CardTitle>
                        <MessageSquare className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{data?.totalComments || 0}</div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Total comments
                        </p>
                    </CardContent>
                </Card>

                <Card className="hover-lift">
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Engagement</CardTitle>
                        <TrendingUp className="h-4 w-4 text-muted-foreground" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">
                            {data?.totalPosts ? ((data.totalComments / data.totalPosts) || 0).toFixed(1) : 0}
                        </div>
                        <p className="text-xs text-muted-foreground mt-1">
                            Comments per post
                        </p>
                    </CardContent>
                </Card>
            </div>

            {/* Popular Posts */}
            <Card>
                <CardHeader>
                    <CardTitle>Popular Posts</CardTitle>
                    <CardDescription>Your most engaging content</CardDescription>
                </CardHeader>
                <CardContent>
                    {data?.popularPosts && data.popularPosts.length > 0 ? (
                        <div className="space-y-4">
                            {data.popularPosts.map((post, index) => (
                                <div
                                    key={post.slug}
                                    className="flex items-center justify-between p-4 rounded-lg border hover:bg-secondary/50 transition-colors"
                                >
                                    <div className="flex items-center gap-4">
                                        <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                                            <span className="text-sm font-bold text-primary">#{index + 1}</span>
                                        </div>
                                        <div>
                                            <h3 className="font-semibold">{post.title}</h3>
                                            <p className="text-sm text-muted-foreground">{post.category}</p>
                                        </div>
                                    </div>
                                    <Button size="sm" variant="outline" asChild>
                                        <Link href={`/blog/${post.slug}`} target="_blank">
                                            View
                                        </Link>
                                    </Button>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="text-center py-12">
                            <p className="text-muted-foreground">No posts yet</p>
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { ArrowLeft, Search, Trash2, Check, X } from "lucide-react";

interface Comment {
    id: string;
    content: string;
    postSlug: string;
    createdAt: string;
    user: {
        name: string | null;
        email: string;
    };
}

export default function CommentsPage() {
    const [comments, setComments] = useState<Comment[]>([]);
    const [filteredComments, setFilteredComments] = useState<Comment[]>([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState("");

    useEffect(() => {
        fetchComments();
    }, []);

    useEffect(() => {
        filterComments();
    }, [searchQuery, comments]);

    const fetchComments = async () => {
        try {
            const response = await fetch("/api/admin/comments");
            const data = await response.json();
            setComments(data.comments || []);
            setFilteredComments(data.comments || []);
        } catch (error) {
            console.error("Failed to fetch comments:", error);
        } finally {
            setLoading(false);
        }
    };

    const filterComments = () => {
        let filtered = comments;

        if (searchQuery) {
            filtered = filtered.filter(comment =>
                comment.content.toLowerCase().includes(searchQuery.toLowerCase()) ||
                comment.user.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
                comment.postSlug.toLowerCase().includes(searchQuery.toLowerCase())
            );
        }

        setFilteredComments(filtered);
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Are you sure you want to delete this comment?")) return;

        try {
            const response = await fetch(`/api/admin/comments/${id}`, {
                method: "DELETE",
            });

            if (response.ok) {
                fetchComments();
            } else {
                alert("Failed to delete comment");
            }
        } catch (error) {
            console.error("Error deleting comment:", error);
            alert("Failed to delete comment");
        }
    };

    if (loading) {
        return (
            <div className="container px-4 md:px-6 py-12">
                <div className="flex items-center justify-center min-h-[400px]">
                    <div className="text-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
                        <p className="text-muted-foreground">Loading comments...</p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container px-4 md:px-6 py-8 md:py-12">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <div className="flex items-center gap-2 mb-2">
                        <Button variant="ghost" size="sm" asChild>
                            <Link href="/admin">
                                <ArrowLeft className="h-4 w-4 mr-2" />
                                Back to Dashboard
                            </Link>
                        </Button>
                    </div>
                    <h1 className="text-3xl md:text-4xl font-bold tracking-tight">Comments Management</h1>
                    <p className="text-muted-foreground mt-2">Moderate and manage user comments</p>
                </div>
            </div>

            {/* Search */}
            <Card className="mb-6">
                <CardHeader>
                    <CardTitle>Search Comments</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                        <Input
                            placeholder="Search by content, author, or post..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="pl-9"
                        />
                    </div>
                </CardContent>
            </Card>

            {/* Comments List */}
            <Card>
                <CardHeader>
                    <CardTitle>Comments ({filteredComments.length})</CardTitle>
                </CardHeader>
                <CardContent>
                    {filteredComments.length === 0 ? (
                        <div className="text-center py-12">
                            <p className="text-muted-foreground">
                                {searchQuery ? "No comments found matching your search" : "No comments yet"}
                            </p>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {filteredComments.map((comment) => (
                                <div
                                    key={comment.id}
                                    className="p-4 rounded-lg border hover:bg-secondary/50 transition-colors"
                                >
                                    <div className="flex items-start justify-between mb-2">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-1">
                                                <span className="font-semibold text-sm">
                                                    {comment.user.name || "Anonymous"}
                                                </span>
                                                <span className="text-xs text-muted-foreground">
                                                    {comment.user.email}
                                                </span>
                                            </div>
                                            <p className="text-sm text-muted-foreground mb-2">
                                                On post: <Link href={`/blog/${comment.postSlug}`} className="text-primary hover:underline">{comment.postSlug}</Link>
                                            </p>
                                            <p className="text-sm">{comment.content}</p>
                                            <p className="text-xs text-muted-foreground mt-2">
                                                {new Date(comment.createdAt).toLocaleString()}
                                            </p>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <Button
                                                size="sm"
                                                variant="ghost"
                                                onClick={() => handleDelete(comment.id)}
                                            >
                                                <Trash2 className="h-4 w-4 text-destructive" />
                                            </Button>
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    )}
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

const ADMIN_EMAILS = [
    "kevaleaditya1@gmail.com",
    "adityakevale2904@gmail.com",
];

export default function AdminForgotPasswordPage() {
    const [email, setEmail] = useState("");
    const [loading, setLoading] = useState(false);
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setMessage("");
        setError("");

        // Check if email is in admin whitelist
        if (!ADMIN_EMAILS.includes(email)) {
            setError("Access denied. Not an admin email.");
            setLoading(false);
            return;
        }

        try {
            const response = await fetch("/api/auth/forgot-password", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ email }),
            });

            const data = await response.json();

            if (response.ok) {
                setMessage("✅ Password reset link sent! Check your email.");
                setEmail("");
            } else {
                setError(data.error || "Failed to send reset link");
            }
        } catch (err) {
            setError("Something went wrong");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-background p-4">
            <Card className="w-full max-w-md">
                <CardHeader>
                    <CardTitle className="text-2xl">Admin Password Reset</CardTitle>
                    <CardDescription>
                        Enter your admin email to receive a reset link
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="space-y-2">
                            <label htmlFor="email" className="text-sm font-medium">
                                Admin Email
                            </label>
                            <Input
                                id="email"
                                type="email"
                                value={email}
                                onChange={(e) => setEmail(e.target.value)}
                                placeholder="admin@example.com"
                                required
                                disabled={loading}
                            />
                        </div>
                        {message && <p className="text-sm text-green-600">{message}</p>}
                        {error && <p className="text-sm text-red-500">{error}</p>}
                        <Button type="submit" className="w-full" disabled={loading}>
                            {loading ? "Sending..." : "Send Reset Link"}
                        </Button>
                        <p className="text-sm text-center text-muted-foreground">
                            Remember your password?{" "}
                            <Link href="/admin/login" className="text-primary hover:underline">
                                Sign in
                            </Link>
                        </p>
                    </form>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState } from "react";
import { signIn } from "next-auth/react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

const ADMIN_EMAILS = [
    "kevaleaditya1@gmail.com",
    "adityakevale2904@gmail.com",
];

export default function AdminLoginPage() {
    const router = useRouter();
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [formData, setFormData] = useState({
        email: "",
        password: "",
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError("");

        // Check if email is in admin whitelist
        if (!ADMIN_EMAILS.includes(formData.email)) {
            setError("Access denied. Not an admin email.");
            setLoading(false);
            return;
        }

        try {
            console.log("Attempting login with:", formData.email);

            await signIn("credentials", {
                email: formData.email,
                password: formData.password,
                redirect: true,
                callbackUrl: "/admin",
            });
        } catch (error) {
            console.error("Login exception:", error);
            setError("An error occurred. Please try again.");
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center bg-background p-4">
            <Card className="w-full max-w-md">
                <CardHeader>
                    <CardTitle className="text-2xl">Admin Login</CardTitle>
                    <CardDescription>
                        Sign in to access the admin panel
                    </CardDescription>
                </CardHeader>
                <CardContent>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <div className="space-y-2">
                            <label htmlFor="email" className="text-sm font-medium">
                                Email
                            </label>
                            <Input
                                id="email"
                                type="email"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                placeholder="admin@example.com"
                                required
                                disabled={loading}
                            />
                        </div>
                        <div className="space-y-2">
                            <div className="flex items-center justify-between">
                                <label htmlFor="password" className="text-sm font-medium">
                                    Password
                                </label>
                                <Link
                                    href="/admin/forgot-password"
                                    className="text-xs text-primary hover:underline"
                                >
                                    Forgot password?
                                </Link>
                            </div>
                            <Input
                                id="password"
                                type="password"
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                placeholder="••••••••"
                                required
                                disabled={loading}
                            />
                        </div>
                        {error && <p className="text-sm text-red-500">{error}</p>}
                        <Button type="submit" className="w-full" disabled={loading}>
                            {loading ? "Signing in..." : "Sign In"}
                        </Button>
                        <p className="text-xs text-muted-foreground text-center mt-4">
                            Only authorized admin emails can access this panel
                        </p>
                    </form>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import {
    Card,
    CardContent,
    CardDescription,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { ArrowLeft, Upload, Copy, Trash2, Image as ImageIcon } from "lucide-react";

interface MediaItem {
    public_id: string;
    secure_url: string;
    created_at: string;
    bytes: number;
    format: string;
}

export default function MediaLibraryPage() {
    const [media, setMedia] = useState<MediaItem[]>([]);
    const [loading, setLoading] = useState(true);
    const [uploading, setUploading] = useState(false);

    useEffect(() => {
        fetchMedia();
    }, []);

    const fetchMedia = async () => {
        try {
            const response = await fetch("/api/admin/media");
            const data = await response.json();
            setMedia(data.resources || []);
        } catch (error) {
            console.error("Failed to fetch media:", error);
        } finally {
            setLoading(false);
        }
    };

    const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (!file) return;

        setUploading(true);
        try {
            const formData = new FormData();
            formData.append("file", file);

            const response = await fetch("/api/upload", {
                method: "POST",
                body: formData,
            });

            const data = await response.json();
            if (data.success) {
                fetchMedia();
            } else {
                alert("Failed to upload image");
            }
        } catch (error) {
            console.error("Upload error:", error);
            alert("Failed to upload image");
        } finally {
            setUploading(false);
        }
    };

    const copyUrl = (url: string) => {
        navigator.clipboard.writeText(url);
        alert("URL copied to clipboard!");
    };

    const formatBytes = (bytes: number) => {
        if (bytes === 0) return "0 Bytes";
        const k = 1024;
        const sizes = ["Bytes", "KB", "MB", "GB"];
        const i = Math.floor(Math.log(bytes) / Math.log(k));
        return Math.round(bytes / Math.pow(k, i) * 100) / 100 + " " + sizes[i];
    };

    if (loading) {
        return (
            <div className="container px-4 md:px-6 py-12">
                <div className="flex items-center justify-center min-h-[400px]">
                    <div className="text-center">
                        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-primary mx-auto mb-4"></div>
                        <p className="text-muted-foreground">Loading media library...</p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="container px-4 md:px-6 py-8 md:py-12">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
                <div>
                    <div className="flex items-center gap-2 mb-2">
                        <Button variant="ghost" size="sm" asChild>
                            <Link href="/admin">
                                <ArrowLeft className="h-4 w-4 mr-2" />
                                Back to Dashboard
                            </Link>
                        </Button>
                    </div>
                    <h1 className="text-3xl md:text-4xl font-bold tracking-tight">Media Library</h1>
                    <p className="text-muted-foreground mt-2">Manage your uploaded images</p>
                </div>
                <div>
                    <input
                        type="file"
                        accept="image/*"
                        onChange={handleUpload}
                        className="hidden"
                        id="media-upload"
                        disabled={uploading}
                    />
                    <Button asChild disabled={uploading}>
                        <label htmlFor="media-upload" className="cursor-pointer">
                            <Upload className="h-4 w-4 mr-2" />
                            {uploading ? "Uploading..." : "Upload Image"}
                        </label>
                    </Button>
                </div>
            </div>

            {/* Media Grid */}
            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
                {media.length === 0 ? (
                    <div className="col-span-full text-center py-20">
                        <ImageIcon className="h-16 w-16 text-muted-foreground mx-auto mb-4" />
                        <p className="text-muted-foreground mb-4">No images uploaded yet</p>
                        <Button asChild>
                            <label htmlFor="media-upload" className="cursor-pointer">
                                <Upload className="h-4 w-4 mr-2" />
                                Upload Your First Image
                            </label>
                        </Button>
                    </div>
                ) : (
                    media.map((item) => (
                        <Card key={item.public_id} className="overflow-hidden hover-lift">
                            <div className="aspect-square relative bg-muted">
                                <img
                                    src={item.secure_url}
                                    alt={item.public_id}
                                    className="w-full h-full object-cover"
                                />
                            </div>
                            <CardContent className="p-4">
                                <p className="text-xs text-muted-foreground mb-2 truncate">
                                    {item.public_id}
                                </p>
                                <div className="flex items-center justify-between text-xs text-muted-foreground mb-3">
                                    <span>{item.format.toUpperCase()}</span>
                                    <span>{formatBytes(item.bytes)}</span>
                                </div>
                                <div className="flex gap-2">
                                    <Button
                                        size="sm"
                                        variant="outline"
                                        className="flex-1"
                                        onClick={() => copyUrl(item.secure_url)}
                                    >
                                        <Copy className="h-3 w-3 mr-1" />
                                        Copy URL
                                    </Button>
                                </div>
                            </CardContent>
                        </Card>
                    ))
                )}
            </div>
        </div>
    );
}

"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowLeft, Save } from "lucide-react";
import Link from "next/link";
import { PostTabs } from "@/components/admin/post-tabs";
import { SEOPanel } from "@/components/admin/seo-panel";
import { SettingsPanel } from "@/components/admin/settings-panel";
import { calculateReadingTime, generateSlug, validatePost } from "@/lib/post-helpers";
import { useToast } from "@/hooks/use-toast";
import { MarkdownEditor } from "@/components/admin/markdown-editor";

interface Props {
    params: Promise<{ slug: string }>;
}

export default function EnhancedEditPostPage({ params }: Props) {
    const router = useRouter();
    const { toast } = useToast();
    const [currentSlug, setCurrentSlug] = useState("");
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);

    // Content fields
    const [title, setTitle] = useState("");
    const [slug, setSlug] = useState("");
    const [excerpt, setExcerpt] = useState("");
    const [content, setContent] = useState("");
    const [coverImage, setCoverImage] = useState("");
    const [category, setCategory] = useState("");
    const [tags, setTags] = useState<string[]>([]);
    const [tagInput, setTagInput] = useState("");

    // SEO fields
    const [metaTitle, setMetaTitle] = useState("");
    const [metaDescription, setMetaDescription] = useState("");
    const [focusKeyword, setFocusKeyword] = useState("");

    // Settings - Visibility
    const [featuredPost, setFeaturedPost] = useState(false);
    const [pinnedPost, setPinnedPost] = useState(false);
    const [trending, setTrending] = useState(false);
    const [showInCategory, setShowInCategory] = useState(true);
    const [hideFromSearch, setHideFromSearch] = useState(false);

    // Settings - Content
    const [contentType, setContentType] = useState("guide");
    const [tableOfContents, setTableOfContents] = useState(true);

    // Settings - Monetization
    const [sponsoredPost, setSponsoredPost] = useState(false);
    const [sponsorName, setSponsorName] = useState("");
    const [affiliateDisclosure, setAffiliateDisclosure] = useState("");
    const [adsEnabled, setAdsEnabled] = useState(true);

    // Settings - Publishing
    const [status, setStatus] = useState("published");
    const [commentEnabled, setCommentEnabled] = useState(true);

    useEffect(() => {
        params.then((p) => {
            setCurrentSlug(p.slug);
            fetchPost(p.slug);
        });
    }, [params]);

    const fetchPost = async (postSlug: string) => {
        try {
            const response = await fetch(`/api/admin/posts/${postSlug}`);
            const data = await response.json();

            if (response.ok && data.post) {
                const post = data.post;

                // Core fields
                setTitle(post.title || "");
                setSlug(post.slug || "");
                setExcerpt(post.excerpt || "");
                setContent(post.content || "");
                setCoverImage(post.coverImage || "");
                setCategory(post.category || "");
                setTags(post.tags || []);

                // SEO fields
                setMetaTitle(post.metaTitle || "");
                setMetaDescription(post.metaDescription || "");
                setFocusKeyword(post.focusKeyword || "");

                // Visibility
                setFeaturedPost(post.featuredPost || false);
                setPinnedPost(post.pinnedPost || false);
                setTrending(post.trending || false);
                setShowInCategory(post.showInCategory !== undefined ? post.showInCategory : true);
                setHideFromSearch(post.hideFromSearch || false);

                // Content
                setContentType(post.contentType || "guide");
                setTableOfContents(post.tableOfContents !== undefined ? post.tableOfContents : true);

                // Monetization
                setSponsoredPost(post.sponsoredPost || false);
                setSponsorName(post.sponsorName || "");
                setAffiliateDisclosure(post.affiliateDisclosure || "");
                setAdsEnabled(post.adsEnabled !== undefined ? post.adsEnabled : true);

                // Publishing
                setStatus(post.status || "published");
                setCommentEnabled(post.commentEnabled !== undefined ? post.commentEnabled : true);
            } else {
                toast({
                    title: "Error",
                    description: "Failed to load post",
                    variant: "destructive",
                });
                router.push("/admin/posts");
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to load post",
                variant: "destructive",
            });
            router.push("/admin/posts");
        } finally {
            setLoading(false);
        }
    };

    const handleAddTag = () => {
        if (tagInput.trim() && !tags.includes(tagInput.trim())) {
            setTags([...tags, tagInput.trim()]);
            setTagInput("");
        }
    };

    const handleRemoveTag = (tagToRemove: string) => {
        setTags(tags.filter(tag => tag !== tagToRemove));
    };

    const handleVisibilityChange = (field: string, value: boolean) => {
        switch (field) {
            case 'featuredPost': setFeaturedPost(value); break;
            case 'pinnedPost': setPinnedPost(value); break;
            case 'trending': setTrending(value); break;
            case 'showInCategory': setShowInCategory(value); break;
            case 'hideFromSearch': setHideFromSearch(value); break;
        }
    };

    const handleMonetizationChange = (field: string, value: boolean | string) => {
        switch (field) {
            case 'sponsoredPost': setSponsoredPost(value as boolean); break;
            case 'sponsorName': setSponsorName(value as string); break;
            case 'affiliateDisclosure': setAffiliateDisclosure(value as string); break;
            case 'adsEnabled': setAdsEnabled(value as boolean); break;
        }
    };

    const handleSubmit = async () => {
        const validation = validatePost({
            title,
            excerpt,
            content,
            coverImage,
            category,
            metaTitle,
            metaDescription,
        });

        if (!validation.valid) {
            toast({
                title: "Validation Error",
                description: validation.errors.join(", "),
                variant: "destructive",
            });
            return;
        }

        setSaving(true);

        try {
            const readingTime = calculateReadingTime(content);

            const response = await fetch(`/api/admin/posts/${currentSlug}`, {
                method: "PUT",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    title,
                    slug,
                    excerpt,
                    content,
                    coverImage,
                    category,
                    tags,
                    metaTitle: metaTitle || title,
                    metaDescription,
                    focusKeyword,
                    readingTime,
                    tableOfContents,
                    contentType,
                    featuredPost,
                    pinnedPost,
                    trending,
                    showInCategory,
                    hideFromSearch,
                    sponsoredPost,
                    sponsorName,
                    affiliateDisclosure,
                    adsEnabled,
                    status,
                    commentEnabled,
                    published: status === "published",
                }),
            });

            if (response.ok) {
                toast({
                    title: "Success!",
                    description: "Post updated successfully",
                });
                router.push("/admin/posts");
            } else {
                throw new Error("Failed to update post");
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to update post. Please try again.",
                variant: "destructive",
            });
        } finally {
            setSaving(false);
        }
    };

    if (loading) {
        return (
            <div className="container max-w-6xl px-4 py-8">
                <div className="text-center">Loading...</div>
            </div>
        );
    }

    return (
        <div className="container max-w-6xl px-4 py-8">
            <div className="flex items-center justify-between mb-8">
                <div className="flex items-center gap-4">
                    <Link href="/admin/posts">
                        <Button variant="ghost" size="icon">
                            <ArrowLeft className="h-4 w-4" />
                        </Button>
                    </Link>
                    <h1 className="text-3xl font-bold">Edit Post</h1>
                </div>
                <Button onClick={handleSubmit} disabled={saving}>
                    <Save className="h-4 w-4 mr-2" />
                    {saving ? "Saving..." : "Update Post"}
                </Button>
            </div>

            <PostTabs>
                {{
                    content: (
                        <div className="space-y-6">
                            <Card>
                                <CardHeader>
                                    <CardTitle>Basic Information</CardTitle>
                                </CardHeader>
                                <CardContent className="space-y-4">
                                    <div className="space-y-2">
                                        <Label htmlFor="title">Title *</Label>
                                        <Input
                                            id="title"
                                            value={title}
                                            onChange={(e) => setTitle(e.target.value)}
                                            maxLength={120}
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <Label htmlFor="slug">Slug</Label>
                                        <Input
                                            id="slug"
                                            value={slug}
                                            onChange={(e) => setSlug(e.target.value)}
                                        />
                                    </div>

                                    <div className="space-y-2">
                                        <Label htmlFor="excerpt">Excerpt *</Label>
                                        <Textarea
                                            id="excerpt"
                                            value={excerpt}
                                            onChange={(e) => setExcerpt(e.target.value)}
                                            rows={3}
                                            maxLength={300}
                                        />
                                        <p className="text-xs text-muted-foreground">{excerpt.length}/300</p>
                                    </div>

                                    <div className="space-y-2">
                                        <Label htmlFor="coverImage">Cover Image URL *</Label>
                                        <Input
                                            id="coverImage"
                                            value={coverImage}
                                            onChange={(e) => setCoverImage(e.target.value)}
                                        />
                                    </div>

                                    <div className="grid grid-cols-2 gap-4">
                                        <div className="space-y-2">
                                            <Label htmlFor="category">Category *</Label>
                                            <Select value={category} onValueChange={setCategory}>
                                                <SelectTrigger>
                                                    <SelectValue />
                                                </SelectTrigger>
                                                <SelectContent>
                                                    <SelectItem value="phones">Phones</SelectItem>
                                                    <SelectItem value="gadgets">Gadgets</SelectItem>
                                                    <SelectItem value="ai-tools">AI Tools</SelectItem>
                                                    <SelectItem value="guides">Guides</SelectItem>
                                                    <SelectItem value="news">News</SelectItem>
                                                </SelectContent>
                                            </Select>
                                        </div>

                                        <div className="space-y-2">
                                            <Label htmlFor="tags">Tags</Label>
                                            <div className="flex gap-2">
                                                <Input
                                                    id="tags"
                                                    value={tagInput}
                                                    onChange={(e) => setTagInput(e.target.value)}
                                                    onKeyPress={(e) => e.key === 'Enter' && (e.preventDefault(), handleAddTag())}
                                                />
                                                <Button type="button" onClick={handleAddTag} variant="outline">
                                                    Add
                                                </Button>
                                            </div>
                                            <div className="flex flex-wrap gap-2 mt-2">
                                                {tags.map(tag => (
                                                    <span key={tag} className="bg-secondary px-2 py-1 rounded text-sm flex items-center gap-1">
                                                        {tag}
                                                        <button onClick={() => handleRemoveTag(tag)} className="text-muted-foreground hover:text-foreground">×</button>
                                                    </span>
                                                ))}
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>

                            <MarkdownEditor
                                value={content}
                                onChange={setContent}
                                placeholder="Write your post content in Markdown..."
                            />
                            <p className="text-xs text-muted-foreground mt-2">
                                {content.split(/\s+/).length} words • {calculateReadingTime(content)} min read
                            </p>
                        </div>
                    ),

                    seo: (
                        <SEOPanel
                            title={title}
                            metaTitle={metaTitle}
                            metaDescription={metaDescription}
                            focusKeyword={focusKeyword}
                            content={content}
                            onMetaTitleChange={setMetaTitle}
                            onMetaDescriptionChange={setMetaDescription}
                            onFocusKeywordChange={setFocusKeyword}
                        />
                    ),

                    settings: (
                        <SettingsPanel
                            featuredPost={featuredPost}
                            pinnedPost={pinnedPost}
                            trending={trending}
                            showInCategory={showInCategory}
                            hideFromSearch={hideFromSearch}
                            contentType={contentType}
                            tableOfContents={tableOfContents}
                            sponsoredPost={sponsoredPost}
                            sponsorName={sponsorName}
                            affiliateDisclosure={affiliateDisclosure}
                            adsEnabled={adsEnabled}
                            commentEnabled={commentEnabled}
                            status={status}
                            onVisibilityChange={handleVisibilityChange}
                            onContentTypeChange={setContentType}
                            onTableOfContentsChange={setTableOfContents}
                            onMonetizationChange={handleMonetizationChange}
                            onCommentEnabledChange={setCommentEnabled}
                            onStatusChange={setStatus}
                        />
                    ),

                    preview: (
                        <Card>
                            <CardHeader>
                                <CardTitle>{title || "Your Post Title"}</CardTitle>
                                <p className="text-sm text-muted-foreground">{excerpt}</p>
                            </CardHeader>
                            <CardContent>
                                <div className="prose max-w-none">
                                    {content || "Your content will appear here..."}
                                </div>
                            </CardContent>
                        </Card>
                    ),
                }}
            </PostTabs>
        </div>
    );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ArrowLeft, Save } from "lucide-react";
import Link from "next/link";
import { PostTabs } from "@/components/admin/post-tabs";
import { SEOPanel } from "@/components/admin/seo-panel";
import { SettingsPanel } from "@/components/admin/settings-panel";
import { calculateReadingTime, generateSlug, validatePost } from "@/lib/post-helpers";
import { useToast } from "@/hooks/use-toast";
import { MarkdownEditor } from "@/components/admin/markdown-editor";

export default function EnhancedNewPostPage() {
    const router = useRouter();
    const { toast } = useToast();
    const [loading, setLoading] = useState(false);

    // Content fields
    const [title, setTitle] = useState("");
    const [slug, setSlug] = useState("");
    const [excerpt, setExcerpt] = useState("");
    const [content, setContent] = useState("");
    const [coverImage, setCoverImage] = useState("");
    const [category, setCategory] = useState("");
    const [tags, setTags] = useState<string[]>([]);
    const [tagInput, setTagInput] = useState("");

    // SEO fields
    const [metaTitle, setMetaTitle] = useState("");
    const [metaDescription, setMetaDescription] = useState("");
    const [focusKeyword, setFocusKeyword] = useState("");

    // Settings - Visibility
    const [featuredPost, setFeaturedPost] = useState(false);
    const [pinnedPost, setPinnedPost] = useState(false);
    const [trending, setTrending] = useState(false);
    const [showInCategory, setShowInCategory] = useState(true);
    const [hideFromSearch, setHideFromSearch] = useState(false);

    // Settings - Content
    const [contentType, setContentType] = useState("guide");
    const [tableOfContents, setTableOfContents] = useState(true);

    // Settings - Monetization
    const [sponsoredPost, setSponsoredPost] = useState(false);
    const [sponsorName, setSponsorName] = useState("");
    const [affiliateDisclosure, setAffiliateDisclosure] = useState("");
    const [adsEnabled, setAdsEnabled] = useState(true);

    // Settings - Publishing
    const [status, setStatus] = useState("published");
    const [commentEnabled, setCommentEnabled] = useState(true);

    // Auto-generate slug from title
    const handleTitleChange = (value: string) => {
        setTitle(value);
        if (!slug) {
            setSlug(generateSlug(value));
        }
    };

    // Handle tag input
    const handleAddTag = () => {
        if (tagInput.trim() && !tags.includes(tagInput.trim())) {
            setTags([...tags, tagInput.trim()]);
            setTagInput("");
        }
    };

    const handleRemoveTag = (tagToRemove: string) => {
        setTags(tags.filter(tag => tag !== tagToRemove));
    };

    // Handle visibility changes
    const handleVisibilityChange = (field: string, value: boolean) => {
        switch (field) {
            case 'featuredPost': setFeaturedPost(value); break;
            case 'pinnedPost': setPinnedPost(value); break;
            case 'trending': setTrending(value); break;
            case 'showInCategory': setShowInCategory(value); break;
            case 'hideFromSearch': setHideFromSearch(value); break;
        }
    };

    // Handle monetization changes
    const handleMonetizationChange = (field: string, value: boolean | string) => {
        switch (field) {
            case 'sponsoredPost': setSponsoredPost(value as boolean); break;
            case 'sponsorName': setSponsorName(value as string); break;
            case 'affiliateDisclosure': setAffiliateDisclosure(value as string); break;
            case 'adsEnabled': setAdsEnabled(value as boolean); break;
        }
    };

    // Submit handler
    const handleSubmit = async () => {
        // Validate
        const validation = validatePost({
            title,
            excerpt,
            content,
            coverImage,
            category,
            metaTitle,
            metaDescription,
        });

        if (!validation.valid) {
            toast({
                title: "Validation Error",
                description: validation.errors.join(", "),
                variant: "destructive",
            });
            return;
        }

        setLoading(true);

        try {
            const readingTime = calculateReadingTime(content);
            const finalSlug = slug || generateSlug(title);

            const response = await fetch("/api/admin/posts", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    // Core fields
                    title,
                    slug: finalSlug,
                    excerpt,
                    content,
                    coverImage,
                    category,
                    tags,

                    // SEO fields
                    metaTitle: metaTitle || title,
                    metaDescription,
                    focusKeyword,

                    // Content enhancement
                    readingTime,
                    tableOfContents,
                    contentType,

                    // Visibility
                    featuredPost,
                    pinnedPost,
                    trending,
                    showInCategory,
                    hideFromSearch,

                    // Monetization
                    sponsoredPost,
                    sponsorName,
                    affiliateDisclosure,
                    adsEnabled,

                    // Technical
                    status,
                    commentEnabled,
                    published: status === "published",
                    publishDate: status === "published" ? new Date() : null,
                }),
            });

            if (response.ok) {
                toast({
                    title: "Success!",
                    description: "Post created successfully",
                });
                router.push("/admin/posts");
            } else {
                throw new Error("Failed to create post");
            }
        } catch (error) {
            toast({
                title: "Error",
                description: "Failed to create post. Please try again.",
                variant: "destructive",
            });
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="container max-w-6xl px-4 py-8">
            {/* Header */}
            <div className="flex items-center justify-between mb-8">
