import { prisma } from '@/lib/prisma';
import { generateMultiplePosts } from '@/lib/ai/blog-generator';
import { submitToIndexNow } from '@/lib/indexnow';

export const dynamic = 'force-dynamic';

export async function GET(request: Request) {
    // Verify cron secret
    const authHeader = request.headers.get('authorization');
    if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
        return new NextResponse('Unauthorized', { status: 401 });
    }

    try {
        console.log('Starting auto blog generation...');

        // Build posts only from current stories. Old items stay in the news
        // archive, but should not be recycled into a new "trending" article.
        const trendingSince = new Date(Date.now() - 24 * 60 * 60 * 1000);
        const topNews = await prisma.newsItem.findMany({
            where: { publishedAt: { gte: trendingSince } },
            orderBy: [{ aiScore: 'desc' }, { publishedAt: 'desc' }],
            take: 50,
            select: {
                title: true,
                summary: true,
                content: true,
                category: true,
                tags: true,
                link: true,
                source: true,
                image: true,
            }
        });

        console.log(`Found ${topNews.length} current news items`);

        if (topNews.length < 3) {
            return NextResponse.json({
                message: 'Not enough news to generate posts',
                generated: 0
            });
        }

        // Syndicate each authorized source item as its own post. The source
        // link is stored as canonicalUrl so scheduled runs remain idempotent.
        const syndicated = [];
        for (const item of topNews) {
            const alreadyPublished = await prisma.post.findFirst({
                where: { canonicalUrl: item.link },
                select: { slug: true },
            });
            if (alreadyPublished) continue;

            const slugBase = item.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
            const postIndex = syndicated.length;
            const slug: string = `${slugBase}-${Date.now()}-${postIndex}`;
            const content = item.content?.trim() || item.summary;
            const excerpt = item.summary.slice(0, 300);
            const post = await prisma.post.create({
                data: {
                    title: item.title,
                    slug,
                    excerpt,
                    content: `${content}\n\n## Original source\n[Read the original article on ${item.source}](${item.link})`,
                    category: item.category,
                    tags: item.tags,
                    coverImage: item.image || '/images/default-blog-cover.jpg',
                    published: true,
                    status: 'published',
                    trending: true,
                    canonicalUrl: item.link,
                    metaTitle: item.title.slice(0, 60),
                    metaDescription: excerpt.slice(0, 160),
                    readingTime: Math.max(1, Math.ceil(content.split(/\s+/).length / 200)),
                    contentType: 'news',
                    schemaType: 'Article',
                },
            });
            syndicated.push({ title: post.title, slug: post.slug, source: item.source });
        }

        try {
            await submitToIndexNow(syndicated.map(post => `${(process.env.NEXT_PUBLIC_SITE_URL || 'https://aanaa.blog').replace(/\/$/, '')}/blog/${post.slug}`));
        } catch (error) {
            console.error('IndexNow submission failed:', error);
        }

        return NextResponse.json({
            success: true,
            mode: 'syndicated',
            generated: syndicated.length,
            posts: syndicated,
        });

        console.log(`Generating blog posts from ${topNews.length} news items...`);

        // Generate 1-2 blog posts using Groq AI (FREE!)
        let generatedPosts = [];
        try {
            console.log('Calling Groq AI to generate posts...');
            const { generateMultiplePosts } = await import('@/lib/ai/blog-generator');
            const formattedNews = topNews.map(item => ({
                ...item,
                content: item.content ?? undefined,
            }));
            generatedPosts = await generateMultiplePosts(formattedNews, 2);
            console.log(`AI generated ${generatedPosts.length} posts`);
        } catch (error) {
            console.error('Error in generateMultiplePosts:', error);
            return NextResponse.json({
                error: 'Failed to generate posts with AI',
                details: error instanceof Error ? String((error as Error).message) : 'Unknown error'
            }, { status: 500 });
        }

        if (generatedPosts.length === 0) {
            return NextResponse.json({
                message: 'AI generated 0 posts',
                generated: 0
            });
        }

        // Save posts to database
        const savedPosts = [];
        const itemsPerPost = Math.ceil(topNews.length / generatedPosts.length);
        for (const [postIndex, post] of generatedPosts.entries()) {
            try {
                const postNews = topNews.slice(postIndex * itemsPerPost, (postIndex + 1) * itemsPerPost);
                // Create slug from title with timestamp to ensure uniqueness
                const slug = post.title
                    .toLowerCase()
                    .replace(/[^a-z0-9]+/g, '-')
                    .replace(/(^-|-$)/g, '') + '-' + Date.now();

                // Fetch cover image from web using Pexels
                let coverImage = postNews.find(item => item.image)?.image || '/images/default-blog-cover.jpg';
                try {
                    if (coverImage === '/images/default-blog-cover.jpg') {
                    const { searchWebImage } = await import('@/lib/pexels');
                    const webImage = await searchWebImage(post.title);
                    if (webImage) {
                        coverImage = String(webImage);
                        console.log(`✓ Found cover image for: ${post.title}`);
                    }
                    }
                } catch (error) {
                    console.error('Error fetching cover image:', error);
                }

                // Replace image placeholders with actual images
                let contentWithImages = post.content;
                const imagePlaceholders = post.content.match(/IMAGE_PLACEHOLDER_\d+/g) || [];

                for (let i = 0; i < imagePlaceholders.length; i++) {
                    const placeholder = imagePlaceholders[i];
                    let imageUrl = null;

                    // Try to get image from news items first
                    const sourceImage = postNews[i % Math.max(postNews.length, 1)]?.image;
                    if (sourceImage) {
                        imageUrl = sourceImage;
                        console.log(`✓ Using news image ${i + 1}`);
                    } else {
                        // Fallback to Pexels search based on post tags
                        try {
                            const { searchWebImage } = await import('@/lib/pexels');
                            const searchTerm = post.tags[i] || post.category;
                            imageUrl = await searchWebImage(searchTerm);
                            if (imageUrl) {
                                console.log(`✓ Found Pexels image for: ${searchTerm}`);
                            }
                        } catch (error) {
                            console.error(`Error fetching image ${i + 1}:`, error);
                        }
                    }

                    // Replace placeholder with actual image URL or remove if not found
                    if (imageUrl) {
                        contentWithImages = contentWithImages.replace(placeholder, imageUrl);
                    } else {
                        // Remove the entire image markdown if no image found
                        contentWithImages = contentWithImages.replace(new RegExp(`!\\[.*?\\]\\(${placeholder}\\)\\s*`, 'g'), '');
                    }
                }

                // Add source references to content
                const newsLinks = postNews.map((news: any) =>
                    `- [${news.title}](${news.link || '#'}) - *${news.source}*`
                ).join('\n');

                const contentWithReferences = `${contentWithImages}\n\n## 📚 Sources & References\n\nThis article was compiled from the following news sources:\n\n${newsLinks}\n\n*Click the links above to read the full articles from the original sources.*`;

                // Create post with comprehensive SEO
                const savedPost = await prisma.post.create({
                    data: {
                        title: post.title,
                        slug,
                        excerpt: post.excerpt,
                        content: contentWithReferences,
                        category: post.category,
                        tags: post.tags,
                        coverImage,
                        published: true,
                        status: 'published',
                        featuredPost: false,
                        trending: true,
                        // SEO Metadata
                        metaTitle: post.title.length > 60 ? post.title.substring(0, 57) + '...' : post.title,
                        metaDescription: post.excerpt.length > 160 ? post.excerpt.substring(0, 157) + '...' : post.excerpt,
                        focusKeyword: post.tags[0] || post.category,
                        canonicalUrl: `https://aanaa.blog/blog/${slug}`,
                        robots: 'index, follow',
                        ogTitle: post.title,
                        ogDescription: post.excerpt.substring(0, 200),
                        readingTime: Math.ceil(post.content.split(' ').length / 200),
                        tableOfContents: true,
                        commentEnabled: true,
                        adsEnabled: true,
                        schemaType: 'Article',
                    }
                });

                savedPosts.push(savedPost);
                console.log(`✓ Created post: ${savedPost.title}`);

            } catch (error) {
                console.error('Error saving post:', error);
            }
        }

        console.log(`Auto-generated ${savedPosts.length} blog posts`);

        return NextResponse.json({
            success: true,
            generated: savedPosts.length,
            posts: savedPosts.map(p => ({ title: p.title, slug: p.slug }))
        });

    } catch (error) {
        console.error('Auto blog generation error:', error);
        return NextResponse.json(
            { error: 'Failed to generate blog posts' },
            { status: 500 }
        );
    }
}

import { NextRequest, NextResponse } from "next/server";
import { getSortedPostsData } from "@/lib/posts";

export async function GET(request: NextRequest) {
    try {
        const searchParams = request.nextUrl.searchParams;
        const query = searchParams.get("q")?.toLowerCase().trim() || "";
        const category = searchParams.get("category")?.toLowerCase().trim();

        if (!query) {
            return NextResponse.json({
                results: [],
                query: "",
                count: 0,
                message: "Please enter a search query",
            });
        }

        // Get all posts
        const allPosts = (await getSortedPostsData(true)).filter(post => !post.hideFromSearch);

        // Search and score posts
        const scoredPosts = allPosts.map((post) => {
            let score = 0;
            const lowerTitle = post.title.toLowerCase();
            const lowerExcerpt = post.excerpt.toLowerCase();
            const lowerContent = post.content.toLowerCase();
            const lowerTags = post.tags.map(tag => tag.toLowerCase());
            const lowerCategory = post.category.toLowerCase();

            // Title match (highest priority)
            if (lowerTitle.includes(query)) {
                score += 10;
            }

            // Excerpt match
            if (lowerExcerpt.includes(query)) {
                score += 5;
            }

            // Tag match
            if (lowerTags.some(tag => tag.includes(query))) {
                score += 3;
            }

            // Content match
            if (lowerContent.includes(query)) {
                score += 1;
            }

            // Category filter
            if (category && lowerCategory !== category) {
                score = 0; // Exclude posts not in selected category
            }

            return { ...post, score };
        });

        // Filter posts with score > 0 and sort by score
        const results = scoredPosts
            .filter((post) => post.score > 0)
            .sort((a, b) => b.score - a.score)
            .map(({ score, ...post }) => post); // Remove score from results

        return NextResponse.json({
            results,
            query,
            count: results.length,
            category: category || null,
        });
    } catch (error) {
        console.error("Search error:", error);
        return NextResponse.json(
            { error: "Failed to search posts" },
            { status: 500 }
        );
    }
}

