// Revalidate every 60 seconds to show latest content
export const revalidate = 60;

interface Props {
    params: Promise<{
        slug: string;
    }>;
}

export async function generateStaticParams() {
    const paths = await getAllPostSlugs();
    return paths.map((path) => ({
        slug: path.params.slug,
    }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
    const { slug } = await params;
    const post = await getPostData(slug);

    if (!post) {
        return {
            title: "Post Not Found",
        };
    }

    const description = plainText(post.metaDescription || "") || plainText(post.excerpt) || `Read ${post.title} and explore its linked sources on Aana.`;
    const metadata = pageMetadata(post.metaTitle || post.title, description, `/blog/${slug}`, `/blog/${slug}/opengraph-image`);
    return {
        ...metadata,
        alternates: { canonical: post.canonicalUrl || `${SITE_URL}/blog/${slug}` },
        robots: { index: !post.hideFromSearch && !post.robots?.includes("noindex"), follow: !post.robots?.includes("nofollow") },
        openGraph: { ...metadata.openGraph, type: "article", publishedTime: post.date, modifiedTime: post.updatedAt, authors: [post.author.name], tags: post.tags },
    };
}

export default async function Post({ params }: Props) {
    const { slug } = await params;
    const post = await getPostData(slug);

    if (!post) {
        notFound();
    }

    // Fetch related posts
    const relatedPosts = await getRelatedPosts(post.slug, post.category, post.tags, 6);

    const baseUrl = SITE_URL;

    // JSON-LD Schema for Article
    const articleSchema = {
        "@context": "https://schema.org",
        "@type": "Article",
        headline: post.title,
        description: post.excerpt,
        image: `${SITE_URL}/blog/${slug}/opengraph-image`,
        datePublished: new Date(post.date).toISOString(),
        dateModified: new Date(post.updatedAt || post.date).toISOString(),
        author: {
            "@type": "Person",
            name: post.author.name,
            url: baseUrl,
        },
        publisher: {
            "@type": "Organization",
            name: "Aana",
            logo: {
                "@type": "ImageObject",
                url: `${baseUrl}/logo.png`,
            },
        },
        mainEntityOfPage: {
            "@type": "WebPage",
            "@id": `${baseUrl}/blog/${slug}`,
        },
    };

    // JSON-LD Schema for Breadcrumbs
    const breadcrumbSchema = {
        "@context": "https://schema.org",
        "@type": "BreadcrumbList",
        itemListElement: [
            {
                "@type": "ListItem",
                position: 1,
                name: "Home",
                item: baseUrl,
            },
            {
                "@type": "ListItem",
                position: 2,
                name: "Blog",
                item: `${baseUrl}/blog`,
            },
            {
                "@type": "ListItem",
                position: 3,
                name: post.title,
                item: `${baseUrl}/blog/${slug}`,
            },
        ],
    };

    return (
        <>
            {/* JSON-LD Schema Markup */}
            <script
                type="application/ld+json"
                dangerouslySetInnerHTML={{ __html: JSON.stringify(articleSchema) }}
            />
            <script
                type="application/ld+json"
                dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbSchema) }}
            />

            <ReadingProgress />
            <div className="container px-4 md:px-8 py-10 md:py-16">
                <div className="grid grid-cols-1 xl:grid-cols-[1fr_260px] gap-12 max-w-7xl mx-auto">
                    <article className="max-w-3xl">
                        <Button variant="glass" size="sm" asChild className="mb-8 gap-1.5 rounded-full text-xs apple-press">
                            <Link href="/">
                                <ArrowLeft className="h-3.5 w-3.5" /> Back to Home
                            </Link>
                        </Button>

                        <div className="space-y-4 mb-10 pb-8 border-b border-border/40">
                            <div className="flex items-center justify-between gap-4">
                                <div className="flex items-center gap-2">
                                    <Badge variant="glass" className="text-xs">{post.category}</Badge>
                                    <span className="text-xs text-muted-foreground flex items-center gap-1">
                                        <Calendar className="h-3 w-3" /> {post.date}
                                    </span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <ShareButtons title={post.title} slug={slug} />
                                    <BookmarkButton postSlug={slug} />
                                </div>
                            </div>

                            <h1 className="text-3xl sm:text-5xl font-bold tracking-tight text-foreground leading-[1.12]">
                                {post.title}
                            </h1>
                            <p className="text-lg sm:text-xl text-muted-foreground leading-relaxed font-normal">
                                {post.excerpt}
                            </p>

                            <div className="flex items-center gap-2 text-xs text-muted-foreground pt-1">
                                <div className="w-5 h-5 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                                    <User className="h-3 w-3" />
                                </div>
                                <span className="font-medium text-foreground">{post.author.name}</span>
                            </div>
                        </div>

                        <div className="prose prose-neutral dark:prose-invert max-w-none prose-headings:font-bold prose-headings:tracking-tight prose-p:leading-relaxed prose-p:text-foreground/90 prose-a:text-primary prose-a:no-underline hover:prose-a:underline">
                            <ReactMarkdown
                                remarkPlugins={[remarkGfm]}
                                rehypePlugins={[rehypeHighlight]}
                                components={{
                                    img: ({ alt, ...props }) => <img {...props} alt={alt || ""} loading="lazy" className="max-w-full h-auto rounded-xl" />,
                                    code: ({ className, children, ...props }) => {
                                        if (!className && !String(children).includes("\n")) {
                                            return <code className={className} {...props}>{children}</code>;
                                        }
                                        return (
                                            <CodeBlock className={className}>
                                                {String(children).replace(/\n$/, '')}
                                            </CodeBlock>
                                        );
                                    },
                                }}
                            >
                                {post.content}
                            </ReactMarkdown>
                        </div>

                        {/* AdSense Ad */}
                        <InArticleAd />

                        <div className="mt-12 pt-8 border-t">
                            <h3 className="text-lg font-semibold mb-4">Tags</h3>
                            <div className="flex flex-wrap gap-2">
                                {post.tags.map((tag) => (
                                    <Badge key={tag} variant="glass" className="hover-lift">
                                        {tag}
                                    </Badge>
                                ))}
                            </div>
                        </div>

                        {/* Related Posts */}
                        <RelatedPosts posts={relatedPosts} />

                        {/* Comments Section */}
                        <CommentsSection postSlug={post.slug} />
                    </article>

                    {/* Table of Contents - Sidebar */}
                    <TableOfContents />
                </div>
            </div>
        </>
    );
}

