"use client";

import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { BookmarkCheck, Trash2, ArrowRight } from "lucide-react";

interface Bookmark {
    id: string;
    postSlug: string;
    createdAt: string;
}

interface Post {
    slug: string;
    title: string;
    excerpt: string;
    date: string;
    category: string;
}

export default function BookmarksPage() {
    const { data: session, status } = useSession();
    const router = useRouter();
    const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
    const [posts, setPosts] = useState<Post[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        if (status === "unauthenticated") {
            router.push("/login");
        } else if (status === "authenticated") {
            fetchData();
        }
    }, [status]);

    const fetchData = async () => {
        try {
            // Fetch bookmarks
            const bookmarksRes = await fetch("/api/bookmarks");
            const bookmarksData = await bookmarksRes.json();
            setBookmarks(bookmarksData.bookmarks || []);

            // Fetch all posts
            const postsRes = await fetch("/api/posts");
            const postsData = await postsRes.json();
            setPosts(postsData.posts || []);
        } catch (error) {
            console.error("Failed to fetch data:", error);
        } finally {
            setLoading(false);
        }
    };

    const removeBookmark = async (postSlug: string) => {
        try {
            const response = await fetch(`/api/bookmarks?postSlug=${postSlug}`, {
                method: "DELETE",
            });
            if (response.ok) {
                setBookmarks(bookmarks.filter((b) => b.postSlug !== postSlug));
            }
        } catch (error) {
            console.error("Failed to remove bookmark:", error);
        }
    };

    if (status === "loading" || loading) {
        return (
            <div className="container px-4 md:px-6 py-12 md:py-20">
                <div className="max-w-4xl mx-auto">
                    <div className="h-8 w-48 bg-secondary rounded animate-pulse mb-8" />
                    <div className="space-y-4">
                        {[1, 2, 3].map((i) => (
                            <Card key={i} className="glass-card animate-pulse">
                                <CardContent className="p-6">
                                    <div className="h-6 bg-secondary rounded w-3/4 mb-2" />
                                    <div className="h-4 bg-secondary rounded w-full" />
                                </CardContent>
                            </Card>
                        ))}
                    </div>
                </div>
            </div>
        );
    }

    const bookmarkedPosts = posts.filter((post) =>
        bookmarks.some((b) => b.postSlug === post.slug)
    );

    return (
        <div className="container px-4 md:px-6 py-12 md:py-20">
            <div className="max-w-4xl mx-auto">
                <div className="mb-8">
                    <h1 className="text-3xl md:text-4xl font-bold mb-2 flex items-center gap-2">
                        <BookmarkCheck className="h-8 w-8" />
                        My Bookmarks
                    </h1>
                    <p className="text-muted-foreground">
                        Articles you've saved for later
                    </p>
                </div>

                {bookmarkedPosts.length === 0 ? (
                    <Card className="p-12 text-center glass-card">
                        <BookmarkCheck className="h-16 w-16 mx-auto mb-4 text-muted-foreground" />
                        <h2 className="text-xl font-semibold mb-2">No bookmarks yet</h2>
                        <p className="text-muted-foreground mb-6">
                            Start saving articles to read them later
                        </p>
                        <Button asChild>
                            <Link href="/">Browse Articles</Link>
                        </Button>
                    </Card>
                ) : (
                    <div className="space-y-4">
                        {bookmarkedPosts.map((post) => (
                            <Card key={post.slug} className="group glass-card hover-lift transition-all overflow-hidden">
                                <CardContent className="p-6">
                                    <div className="flex items-start justify-between gap-4">
                                        <div className="flex-1">
                                            <div className="flex items-center gap-2 mb-2">
                                                <Badge variant="glass">{post.category}</Badge>
                                                <span className="text-xs text-muted-foreground">
                                                    {post.date}
                                                </span>
                                            </div>
                                            <Link href={`/blog/${post.slug}`}>
                                                <h3 className="text-xl font-semibold mb-2 group-hover:text-primary transition-colors">
                                                    {post.title}
                                                </h3>
                                            </Link>
                                            <p className="text-muted-foreground text-sm mb-4">
                                                {post.excerpt}
                                            </p>
                                            <div className="flex items-center gap-3">
                                                <Button variant="ghost" size="sm" asChild>
                                                    <Link href={`/blog/${post.slug}`} className="gap-2">
                                                        Read Article <ArrowRight className="h-4 w-4" />
                                                    </Link>
                                                </Button>
                                                <Button
                                                    variant="ghost"
                                                    size="sm"
                                                    onClick={() => removeBookmark(post.slug)}
                                                    className="text-destructive hover:text-destructive gap-2"
                                                >
                                                    <Trash2 className="h-4 w-4" />
                                                    Remove
                                                </Button>
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        ))}
                    </div>
                )}
            </div>
        </div>
    );
}

import { pageMetadata } from "@/lib/site";
import { notFound } from "next/navigation";
import Link from "next/link";
import Image from "next/image";
import { ArrowRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
    Card,
    CardContent,
    CardDescription,
    CardFooter,
    CardHeader,
    CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { getSortedPostsData } from "@/lib/posts";

interface Props {
    params: Promise<{
        slug: string;
    }>;
}

export async function generateStaticParams() {
    const posts = await getSortedPostsData();
    const categories = Array.from(new Set(posts.map((post) => post.category.toLowerCase().replace(/\s+/g, "-"))));

    return categories.map((slug) => ({
        slug,
    }));
}

export async function generateMetadata({ params }: Props) {
    const { slug } = await params;
    const categoryName = slug
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" ");

    return pageMetadata(`${categoryName} articles`, `Explore ${categoryName} news, reviews and practical guides on Aana.`, `/category/${encodeURIComponent(slug)}`);
}

export default async function CategoryPage({ params }: Props) {
    const { slug } = await params;
    const categoryName = slug
        .split("-")
        .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
        .join(" ");


    const allPosts = await getSortedPostsData();
    const categoryPosts = allPosts.filter((post) => {
        const postCategorySlug = post.category.toLowerCase().replace(/\s+/g, "-");
        return postCategorySlug === slug;
    });

    if (!categoryPosts.length) notFound();

    return (
        <div className="container px-4 md:px-6 py-12 md:py-20">
            <div className="mb-8">
                <h1 className="text-3xl md:text-5xl font-bold tracking-tighter mb-4">
                    {categoryName}
                </h1>
                <p className="text-muted-foreground text-lg">
                    Explore the latest articles, news, and reviews in {categoryName}.
                </p>
            </div>

            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {categoryPosts.length > 0 ? (
                    categoryPosts.map((post, index) => {
                        // Subtle theme colors for light and dark modes
                        const themes = [
                            'from-indigo-50/50 to-purple-50/50 dark:from-indigo-950/20 dark:to-purple-950/20',
                            'from-blue-50/50 to-cyan-50/50 dark:from-blue-950/20 dark:to-cyan-950/20',
                            'from-violet-50/50 to-pink-50/50 dark:from-violet-950/20 dark:to-pink-950/20',
                        ];

                        return (
                            <Link key={post.slug} href={`/blog/${post.slug}`} className="block h-full">
                                <Card className="glass-card hover-lift cursor-pointer flex flex-col h-full overflow-hidden transition-all duration-300">
                                    <CardHeader className="p-0">
                                        <div className="aspect-[16/9] w-full bg-gradient-to-br from-muted/80 to-muted rounded-t-lg overflow-hidden relative">
                                            {post.coverImage ? (
                                                <Image
                                                    src={post.coverImage}
                                                    alt=""
                                                    fill
                                                    className="object-cover"
                                                    sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                                                />
                                            ) : (
                                                <div className="w-full h-full flex items-center justify-center text-muted-foreground">
                                                    <span className="font-medium">{post.title}</span>
                                                </div>
                                            )}
                                        </div>
                                    </CardHeader>
                                    <CardContent className="flex-1 p-6">
                                        <div className="flex items-center gap-2 mb-2 flex-wrap">
                                            <Badge variant="glass" className="text-xs">
                                                {post.category}
                                            </Badge>
                                            {post.pinnedPost && (
                                                <Badge variant="default" className="text-xs">
                                                    📌 Pinned
                                                </Badge>
                                            )}
                                            {post.trending && (
                                                <Badge variant="destructive" className="text-xs">
                                                    🔥 Trending
                                                </Badge>
                                            )}
                                            <span className="text-xs text-muted-foreground">
                                                {post.date}
                                            </span>
                                        </div>
                                        <CardTitle className="line-clamp-2 mb-2">
                                            {post.title}
                                        </CardTitle>
                                        <CardDescription className="line-clamp-3">
                                            {post.excerpt}
                                        </CardDescription>
                                    </CardContent>
                                    <CardFooter className="p-6 pt-0">
                                        <div className="ml-auto flex items-center gap-1 text-sm text-primary font-medium">
                                            Read More <ArrowRight className="h-3 w-3" />
                                        </div>
                                    </CardFooter>
                                </Card>
                            </Link>
                        );
                    })
                ) : (
                    <div className="col-span-full text-center py-20">
                        <p className="text-muted-foreground">No articles found in this category.</p>
                        <Button asChild className="mt-4">
                            <Link href="/">Go Home</Link>
                        </Button>
                    </div>
                )}
            </div>
        </div>
    );
}

import { pageMetadata } from "@/lib/site";
import Link from "next/link";
import { getSortedPostsData } from "@/lib/posts";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";

export const metadata = pageMetadata('Browse Technology Categories', 'Find Aana articles by topic, from smartphones and gadgets to AI tools and technology guides.', '/category');

export default async function CategoriesPage() {
    const allPosts = await getSortedPostsData();

    // Get all unique categories with post counts
    const categoryMap = new Map<string, { name: string; count: number; slug: string }>();

    allPosts.forEach((post) => {
        const slug = post.category.toLowerCase().replace(/\s+/g, "-");
        if (categoryMap.has(slug)) {
            const cat = categoryMap.get(slug)!;
            cat.count++;
        } else {
            categoryMap.set(slug, {
                name: post.category,
                count: 1,
                slug: slug,
            });
        }
    });

    const categories = Array.from(categoryMap.values()).sort((a, b) => b.count - a.count);

    // Category icons/colors
    const categoryThemes = [
        { gradient: 'from-indigo-500 to-purple-500', bg: 'from-indigo-50 to-purple-50 dark:from-indigo-950/30 dark:to-purple-950/30' },
        { gradient: 'from-blue-500 to-cyan-500', bg: 'from-blue-50 to-cyan-50 dark:from-blue-950/30 dark:to-cyan-950/30' },
        { gradient: 'from-violet-500 to-pink-500', bg: 'from-violet-50 to-pink-50 dark:from-violet-950/30 dark:to-pink-950/30' },
        { gradient: 'from-emerald-500 to-teal-500', bg: 'from-emerald-50 to-teal-50 dark:from-emerald-950/30 dark:to-teal-950/30' },
        { gradient: 'from-orange-500 to-red-500', bg: 'from-orange-50 to-red-50 dark:from-orange-950/30 dark:to-red-950/30' },
        { gradient: 'from-pink-500 to-rose-500', bg: 'from-pink-50 to-rose-50 dark:from-pink-950/30 dark:to-rose-950/30' },
    ];

    return (
        <div className="container px-4 md:px-8 max-w-7xl mx-auto py-12 md:py-20">
            <div className="mb-12 max-w-3xl">
                <span className="text-xs font-semibold uppercase tracking-wider text-primary mb-2 block">
                    Directory
                </span>
                <h1 className="text-3xl sm:text-5xl font-bold tracking-tight text-foreground mb-3">
                    Browse Topics & Categories
                </h1>
                <p className="text-muted-foreground text-base sm:text-lg leading-relaxed">
                    Explore curated tech intelligence categorized by domain — from smartphone hardware architectures to emerging neural networks.
                </p>
            </div>

            <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
                {categories.map((category) => (
                    <Link key={category.slug} href={`/category/${category.slug}`} className="group block h-full">
                        <Card className="h-full rounded-2xl border border-black/[0.06] dark:border-white/[0.08] glass-card hover-lift transition-all p-6 flex flex-col justify-between">
                            <CardHeader className="p-0 mb-6">
                                <div className="w-10 h-10 rounded-2xl glass-subtle border border-black/[0.06] dark:border-white/[0.08] flex items-center justify-center text-foreground font-semibold text-base mb-4 group-hover:bg-primary group-hover:text-primary-foreground transition-all shadow-xs">
                                    {category.name.charAt(0)}
                                </div>
                                <CardTitle className="text-xl font-semibold tracking-tight text-foreground group-hover:text-primary transition-colors">
                                    {category.name}
                                </CardTitle>
                                <CardDescription className="mt-1">
                                    <Badge variant="glass" className="text-[11px] font-normal">
                                        {category.count} {category.count === 1 ? 'article' : 'articles'}
                                    </Badge>
                                </CardDescription>
                            </CardHeader>
                            <CardContent className="p-0">
                                <p className="text-xs text-muted-foreground leading-relaxed">
                                    Explore all analysis and reviews in {category.name} →
                                </p>
                            </CardContent>
                        </Card>
                    </Link>
                ))}
            </div>

            {categories.length === 0 && (
                <div className="text-center py-20">
                    <p className="text-muted-foreground">No categories available yet.</p>
                </div>
            )}
        </div>
    );
}

"use client";

import { isEmail } from "@/lib/validation";
import { Suspense, useState, useRef } from "react";
import { signIn } from "next-auth/react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";

function LoginForm() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const requestedCallback = searchParams.get("callbackUrl") || "/";
    const callbackUrl = requestedCallback.startsWith("/") && !requestedCallback.startsWith("//") && !requestedCallback.includes("\\") ? requestedCallback : "/";
    const inFlight = useRef(false);

    const [loading, setLoading] = useState(false);
    const [error, setError] = useState("");
    const [formData, setFormData] = useState({
        email: "",
        password: "",
    });

    const handleGoogleLogin = async () => {
        if (inFlight.current) return;
        inFlight.current = true; setLoading(true); setError("");
        try { await signIn("google", { callbackUrl }); }
        catch { setError("Google sign-in could not start. Please try again."); }
        finally { inFlight.current = false; setLoading(false); }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (inFlight.current) return;
        if (!isEmail(formData.email) || !formData.password) {
            setError("Enter a valid email address and your password.");
            document.getElementById("email")?.focus(); return;
        }
        inFlight.current = true; setLoading(true); setError("");
        try {
            const result = await signIn("credentials", { email: formData.email.trim().toLowerCase(), password: formData.password, redirect: false });
            if (!result?.ok || result.error) setError("Invalid email or password. Please check both fields.");
            else router.push(callbackUrl);
        } catch { setError("Couldn’t connect. Your entries have been kept. Please try again."); }
        finally { inFlight.current = false; setLoading(false); }
    };

    return (
        <div className="min-h-[85vh] flex items-center justify-center bg-background px-4 py-12">
            <div className="w-full max-w-[420px] rounded-3xl glass-floating p-6 md:p-8 shadow-2xl space-y-6">
                <div className="text-center space-y-1.5">
                    <span className="text-xs font-semibold uppercase tracking-wider text-primary">
                        Account Access
                    </span>
                    <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground">
                        Welcome Back
                    </h1>
                    <p className="text-xs text-muted-foreground">
                        Sign in to sync bookmarks and participate in discussions
                    </p>
                </div>

                <div className="space-y-4">
                    <Button
                        onClick={handleGoogleLogin}
                        className="w-full h-10 rounded-full border border-black/[0.1] dark:border-white/[0.12] bg-background hover:bg-black/[0.03] dark:hover:bg-white/[0.05] text-foreground text-xs font-medium apple-press"
                        variant="outline"
                        disabled={loading}
                    >
                        <svg className="w-4 h-4 mr-2" viewBox="0 0 24 24">
                            <path fill="currentColor" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" />
                            <path fill="currentColor" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" />
                            <path fill="currentColor" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" />
                            <path fill="currentColor" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" />
                        </svg>
                        Continue with Google
                    </Button>

                    <div className="relative my-2">
                        <div className="absolute inset-0 flex items-center">
                            <span className="w-full border-t border-border/60" />
                        </div>
                        <div className="relative flex justify-center text-[11px] uppercase tracking-wider">
                            <span className="bg-transparent backdrop-blur-md px-3 text-muted-foreground">
                                or sign in with email
                            </span>
                        </div>
                    </div>

                    <form noValidate aria-busy={loading} onSubmit={handleSubmit} className="space-y-4">
                        <div className="space-y-1.5">
                            <label htmlFor="email" className="text-xs font-medium text-foreground">
                                Email
                            </label>
                            <Input
                                id="email" autoComplete="email" aria-invalid={Boolean(error)} aria-describedby={error ? "login-error" : undefined}
                                type="email"
                                value={formData.email}
                                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                                placeholder="name@domain.com"
                                className="h-10 rounded-xl glass-input text-xs px-3.5"
                                required
                                disabled={loading}
                            />
                        </div>
                        <div className="space-y-1.5">
                            <div className="flex items-center justify-between">
                                <label htmlFor="password" className="text-xs font-medium text-foreground">
                                    Password
                                </label>
                                <Link
                                    href="/forgot-password"
                                    className="text-[11px] text-primary hover:underline underline-offset-4"
                                >
                                    Forgot password?
                                </Link>
                            </div>
                            <Input
                                id="password" autoComplete="current-password" aria-invalid={Boolean(error)} aria-describedby={error ? "login-error" : undefined}
                                type="password"
                                value={formData.password}
                                onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                                placeholder="••••••••"
                                className="h-10 rounded-xl bg-black/[0.02] dark:bg-white/[0.04] text-xs px-3.5"
                                required
                                disabled={loading}
                            />
                        </div>
                        {error && <p id="login-error" role="alert" className="text-xs text-red-500 font-medium">{error}</p>}
                        <Button type="submit" className="w-full h-10 rounded-full bg-foreground text-background hover:opacity-90 text-xs font-medium apple-press mt-2" disabled={loading}>
                            {loading ? "Authenticating..." : "Sign In"}
                        </Button>
                    </form>

                    <p className="text-xs text-center text-muted-foreground pt-2">
                        Need an account?{" "}
                        <Link href="/signup" className="text-primary font-medium hover:underline underline-offset-4">
                            Sign up
                        </Link>
                    </p>
                </div>
            </div>
        </div>
    );
}

export default function LoginPage() {
    return (
        <Suspense fallback={<div className="min-h-screen flex items-center justify-center">Loading...</div>}>
            <LoginForm />
        </Suspense>
    );
}

import { Suspense } from 'react';
import { prisma } from '@/lib/prisma';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import Link from 'next/link';
import Image from 'next/image';

export const dynamic = 'force-dynamic';

interface SearchParams {
    category?: string;
    page?: string;
}

export default async function NewsPage({
    searchParams,
}: {
    searchParams: Promise<SearchParams>;
}) {
    const params = await searchParams;
    const category = params.category;
    const page = Math.max(1, Math.min(10000, Number.parseInt(params.page || '1', 10) || 1));
    const perPage = 12;

    // Fetch news items
    const where = category ? { category } : {};

    const [news, total] = await Promise.all([
        prisma.newsItem.findMany({
            where,
            orderBy: { publishedAt: 'desc' },
            take: perPage,
            skip: (page - 1) * perPage,
        }),
        prisma.newsItem.count({ where }),
    ]);

    const totalPages = Math.ceil(total / perPage);

    // Get unique categories
    const categories = await prisma.newsItem.findMany({
        select: { category: true },
        distinct: ['category'],
    });

    return (
        <div className="container mx-auto max-w-7xl px-4 md:px-8 py-12">
            <div className="mb-8">
                <h1 className="text-4xl font-bold mb-4">Latest Tech News</h1>
                <p className="text-muted-foreground">
                    AI-curated tech news from top sources
                </p>
            </div>

            {/* Category Filter */}
            <div className="flex gap-2 mb-8 flex-wrap">
                <Link href="/news">
                    <Badge variant={!category ? 'default' : 'glass'}>
                        All
                    </Badge>
                </Link>
                {categories.map((cat) => (
                    <Link key={cat.category} href={`/news?category=${cat.category}`}>
                        <Badge variant={category === cat.category ? 'default' : 'glass'}>
                            {cat.category}
                        </Badge>
                    </Link>
                ))}
            </div>

            {/* News Grid */}
            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                {news.map((item) => (
                    <a
                        key={item.id}
                        href={item.link}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="block h-full"
                    >
                        <Card className="h-full glass-card hover-lift transition-all overflow-hidden">
                            {item.image && (
                                <div className="aspect-video relative overflow-hidden rounded-t-lg">
                                    <Image
                                        src={item.image}
                                        alt=""
                                        fill
                                        className="object-cover"
                                        sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                                    />
                                </div>
                            )}
                            <CardHeader>
                                <div className="flex flex-wrap gap-2 mb-2">
                                    <Badge variant="secondary" className="text-xs">
                                        {item.source}
                                    </Badge>
                                    <Badge variant="outline" className="text-xs">
                                        {item.category}
                                    </Badge>
                                </div>
                                <CardTitle className="line-clamp-2">{item.title}</CardTitle>
                                <CardDescription className="text-xs">
                                    {new Date(item.publishedAt).toLocaleDateString()}
                                </CardDescription>
                            </CardHeader>
                            <CardContent>
                                <p className="text-sm text-muted-foreground line-clamp-3">
                                    {item.summary}
                                </p>
                                <div className="flex gap-1 mt-3 flex-wrap">
                                    {item.tags.slice(0, 3).map((tag) => (
                                        <Badge key={tag} variant="outline" className="text-xs">
                                            {tag}
                                        </Badge>
                                    ))}
                                </div>
                            </CardContent>
                        </Card>
                    </a>
                ))}
            </div>

            {/* Pagination */}
            {totalPages > 1 && (
                <div className="flex justify-center gap-2 mt-8">
                    {page > 1 && (
                        <Link
                            href={`/news?${category ? `category=${category}&` : ''}page=${page - 1}`}
                            className="px-4 py-2 border rounded hover:bg-muted"
                        >
                            Previous
                        </Link>
                    )}
                    <span className="px-4 py-2">
                        Page {page} of {totalPages}
                    </span>
                    {page < totalPages && (
                        <Link
                            href={`/news?${category ? `category=${category}&` : ''}page=${page + 1}`}
                            className="px-4 py-2 border rounded hover:bg-muted"
                        >
                            Next
                        </Link>
                    )}
                </div>
            )}

            {news.length === 0 && (
                <div className="text-center py-12">
                    <p className="text-muted-foreground">No news items found.</p>
                    <p className="text-sm text-muted-foreground mt-2">
                        News is automatically refreshed daily.
                    </p>
                </div>
            )}
        </div>
    );
}

import { pageMetadata } from "@/lib/site";
import Link from "next/link";
import Image from "next/image";
import { ArrowRight, TrendingUp } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { getSortedPostsData } from "@/lib/posts";
import { NewsletterSection } from "@/components/newsletter/newsletter-section";

// Revalidate immediately to show latest posts
export const revalidate = 0;

export const metadata = pageMetadata('Tech for the Future', "Smartphone reviews, gadget guides and AI insights. Explore Aana's latest technology articles.", '/');

export default async function Home() {
  const allPosts = await getSortedPostsData();

  // Get actual featured post or fallback to first post
  const featuredPost = allPosts.find(p => p.featuredPost) || allPosts[0];
  const latestPosts = allPosts.slice(0, 12);

  // Calculate trending topics from tags
  const tagCount = new Map<string, number>();
  allPosts.forEach(post => {
    post.tags.forEach(tag => {
      tagCount.set(tag, (tagCount.get(tag) || 0) + 1);
    });
  });

  // Get top 6 most popular tags
  const trendingTopics = Array.from(tagCount.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([tag]) => tag);

  return (
    <div className="flex flex-col min-h-screen">
      {/* Hero Section - Apple Newsroom Style with Glass Accents */}
      <section className="relative pt-16 pb-12 md:pt-24 md:pb-16 overflow-hidden">
        <div className="container px-4 md:px-8 max-w-7xl mx-auto">
          <div className="max-w-3xl space-y-6">
            <div className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full glass-subtle text-primary text-[12px] font-semibold uppercase tracking-wider shadow-xs">
              <span className="w-1.5 h-1.5 rounded-full bg-primary animate-pulse" />
              <span>Next-Gen Tech Editorial</span>
            </div>
            
            <h1 className="text-4xl sm:text-6xl md:text-7xl font-bold tracking-tight text-foreground leading-[1.06]">
              Future tech, <br />
              <span className="text-muted-foreground font-normal">distilled for everyone.</span>
            </h1>

            <p className="text-lg md:text-xl text-muted-foreground font-normal leading-relaxed max-w-2xl">
              Independent analysis, deep smartphone reviews, actionable gadget guides, and curated AI insights.
            </p>

            <div className="flex flex-wrap items-center gap-3 pt-2">
              <Button asChild size="lg" className="rounded-full px-6 gap-2 bg-foreground text-background hover:opacity-90 apple-press shadow-md">
                <Link href="/blog">
                  Explore Articles <ArrowRight className="h-4 w-4" />
                </Link>
              </Button>
              <Button variant="glass" size="lg" asChild className="rounded-full px-6 apple-press">
                <Link href="/category">Browse Categories</Link>
              </Button>
            </div>
          </div>
        </div>
      </section>

      {/* Featured Story Bento Showcase with Liquid Glass Treatment */}
      {featuredPost && (
        <section className="pb-12 md:pb-16">
          <div className="container px-4 md:px-8 max-w-7xl mx-auto">
            <div className="mb-4 flex items-center justify-between">
              <span className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                Featured Story
              </span>
            </div>

            <Link href={`/blog/${featuredPost.slug}`} className="group block">
              <div className="relative rounded-3xl overflow-hidden glass-card hover-lift transition-all">
                <div className="grid grid-cols-1 lg:grid-cols-12 gap-0 items-center">
                  {/* Image Column */}
                  <div className="lg:col-span-7 relative aspect-[16/10] lg:aspect-[16/11] w-full overflow-hidden bg-muted">
                    {featuredPost.coverImage ? (
                      <Image
                        src={featuredPost.coverImage}
                        alt=""
                        fill
                        className="object-cover group-hover:scale-[1.02] transition-transform duration-700 ease-out"
                        priority
                        sizes="(max-width: 1024px) 100vw, 60vw"
                      />
                    ) : (
                      <div className="w-full h-full flex items-center justify-center text-muted-foreground">
                        <span className="font-medium">{featuredPost.title}</span>
                      </div>
                    )}
                  </div>

                  {/* Content Column */}
                  <div className="lg:col-span-5 p-6 md:p-10 lg:p-12 flex flex-col justify-between space-y-6">
                    <div className="space-y-4">
                      <div className="flex items-center gap-2 flex-wrap">
                        <Badge variant="default" className="text-xs">
                          {featuredPost.category}
                        </Badge>
                        <span className="text-xs text-muted-foreground">
                          {featuredPost.date}
                        </span>
                      </div>

                      <h2 className="text-2xl sm:text-3xl lg:text-4xl font-bold tracking-tight text-foreground group-hover:text-primary transition-colors leading-tight">
                        {featuredPost.title}
                      </h2>

                      <p className="text-muted-foreground text-sm sm:text-base leading-relaxed line-clamp-3">
                        {featuredPost.excerpt}
                      </p>
                    </div>

                    <div className="pt-2">
                      <span className="inline-flex items-center gap-1.5 text-sm font-medium text-primary group-hover:underline underline-offset-4">
                        Read Story <ArrowRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />
                      </span>
                    </div>
                  </div>
                </div>
              </div>
            </Link>
          </div>
        </section>
      )}

      {/* Trending Topics Frosted Glass Strip */}
      {trendingTopics.length > 0 && (
        <section className="py-6 border-y border-black/[0.05] dark:border-white/[0.08] glass-subtle">
          <div className="container px-4 md:px-8 max-w-7xl mx-auto flex flex-col sm:flex-row sm:items-center gap-4">
            <div className="flex items-center gap-2 text-xs font-semibold uppercase tracking-wider text-muted-foreground shrink-0">
              <TrendingUp className="h-4 w-4 text-primary" />
              <span>Trending</span>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              {trendingTopics.map((topic) => (
                <Link
                  key={topic}
                  href={`/search?q=${encodeURIComponent(topic)}`}
                  className="px-3.5 py-1 text-xs font-medium rounded-full glass-subtle text-foreground hover:bg-black/[0.06] dark:hover:bg-white/[0.1] hover-lift transition-all shadow-xs"
                >
                  {topic}
                </Link>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Latest Articles Bento Grid with Frosted Glass Cards */}
      <section className="py-12 md:py-20 lg:py-24">
        <div className="container px-4 md:px-8 max-w-7xl mx-auto">
          <div className="flex items-center justify-between mb-8 md:mb-12">
            <div>
              <span className="text-xs font-semibold uppercase tracking-wider text-primary mb-1 block">
                Latest Updates
              </span>
              <h2 className="text-2xl md:text-3xl font-bold tracking-tight text-foreground">
                All Stories & Reviews
              </h2>
            </div>
            <Link
              href="/blog"
              className="text-xs md:text-sm font-medium text-primary hover:underline underline-offset-4 flex items-center gap-1"
            >
              View all <ArrowRight className="h-3 w-3" />
            </Link>
          </div>

          <div className="grid gap-6 sm:grid-cols-2 lg:grid-cols-3">
            {latestPosts.map((post, index) => (
              <Link key={post.slug} href={`/blog/${post.slug}`} className="group block h-full">
                <Card className="flex flex-col h-full rounded-2xl glass-card hover-lift transition-all overflow-hidden">
                  <CardHeader className="p-0">
                    <div className="aspect-[16/10] w-full bg-muted overflow-hidden relative">
                      {post.coverImage ? (
                        <Image
                          src={post.coverImage}
                          alt=""
                          fill
                          className="object-cover group-hover:scale-[1.03] transition-transform duration-500 ease-out"
                          sizes="(max-width: 768px) 100vw, (max-width: 1200px) 50vw, 33vw"
                          priority={false}
                          loading="lazy"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-muted-foreground p-4 text-center">
                          <span className="font-medium text-sm">{post.title}</span>
                        </div>
                      )}
                    </div>
                  </CardHeader>
                  <CardContent className="flex-1 p-5 md:p-6 flex flex-col justify-between">
                    <div>
                      <div className="flex items-center gap-2 mb-3 flex-wrap">
                        <Badge variant="glass" className="text-[11px]">
                          {post.category}
                        </Badge>
                        {post.trending && (
                          <span className="text-[11px] font-semibold text-amber-600 dark:text-amber-400">
                            Trending
                          </span>
                        )}
                        <span className="text-xs text-muted-foreground ml-auto">
                          {post.date}
                        </span>
                      </div>
                      <CardTitle className="text-lg md:text-xl font-semibold tracking-tight text-foreground group-hover:text-primary transition-colors line-clamp-2 mb-2 leading-snug">
                        {post.title}
                      </CardTitle>
                      <CardDescription className="line-clamp-2 text-sm text-muted-foreground leading-relaxed">
                        {post.excerpt}
                      </CardDescription>
                    </div>

                    <div className="pt-4 mt-auto flex items-center text-xs font-medium text-primary">
                      <span>Read Story</span>
                      <ArrowRight className="h-3 w-3 ml-1 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </CardContent>
                </Card>
              </Link>
            ))}
          </div>
        </div>
      </section>

      {/* Newsletter Bento Section with Glass Card */}
      <NewsletterSection />
    </div>
  );
}

import { auth } from "@/lib/auth";
import { redirect } from "next/navigation";
import { privateMetadata } from "@/lib/site";
import { Metadata } from "next";
import { notFound } from "next/navigation";
import { prisma } from "@/lib/prisma";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { MessageCircle, Bookmark, Calendar, User as UserIcon } from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";
import { getPostData } from "@/lib/posts";

interface Props {
    params: Promise<{ id: string }>;
}

export const metadata = privateMetadata("Your profile");

export default async function ProfilePage({ params }: Props) {
    const { id } = await params;
    const session = await auth();
    if (!session?.user) redirect("/login");
    if (session.user.id !== id && session.user.role !== "ADMIN") notFound();

    const user = await prisma.user.findUnique({
        where: { id },
        include: {
            comments: {
                orderBy: { createdAt: "desc" },
                take: 20,
            },
            bookmarks: {
                orderBy: { createdAt: "desc" },
                take: 20,
            },
        },
    });

    if (!user) {
        notFound();
    }

    // Fetch post data for comments
    const commentsWithPosts = await Promise.all(
        user.comments.map(async (comment) => {
            try {
                const post = await getPostData(comment.postSlug);
                return { ...comment, post };
            } catch {
                return { ...comment, post: null };
            }
        })
    );

    // Fetch post data for bookmarks
    const bookmarksWithPosts = await Promise.all(
        user.bookmarks.map(async (bookmark) => {
            try {
                const post = await getPostData(bookmark.postSlug);
                return { ...bookmark, post };
            } catch {
                return { ...bookmark, post: null };
            }
        })
    );

    const validComments = commentsWithPosts.filter((c) => c.post !== null);
    const validBookmarks = bookmarksWithPosts.filter((b) => b.post !== null);

    return (
        <div className="container px-4 md:px-6 py-12 md:py-20">
            <div className="max-w-4xl mx-auto">
                {/* Profile Header */}
                <Card className="mb-8">
                    <CardContent className="pt-6">
                        <div className="flex items-start gap-6">
                            <Avatar className="h-24 w-24">
                                <AvatarImage src={user.image || undefined} alt="" />
                                <AvatarFallback className="text-2xl">
                                    {user.name?.charAt(0) || user.email?.charAt(0) || "U"}
                                </AvatarFallback>
                            </Avatar>
                            <div className="flex-1">
                                <h1 className="text-3xl font-bold mb-2">{user.name || "Anonymous User"}</h1>
                                <p className="text-muted-foreground mb-4">{user.email}</p>
                                <div className="flex items-center gap-2 text-sm text-muted-foreground">
                                    <Calendar className="h-4 w-4" />
                                    Joined {formatDistanceToNow(new Date(user.createdAt), { addSuffix: true })}
                                </div>
                            </div>
                        </div>
                    </CardContent>
                </Card>

                {/* Stats Cards */}
                <div className="grid grid-cols-2 gap-4 mb-8">
                    <Card>
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">Comments</CardTitle>
                            <MessageCircle className="h-4 w-4 text-muted-foreground" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold">{user.comments.length}</div>
                            <p className="text-xs text-muted-foreground">Total comments posted</p>
                        </CardContent>
                    </Card>
                    <Card>
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <CardTitle className="text-sm font-medium">Bookmarks</CardTitle>
                            <Bookmark className="h-4 w-4 text-muted-foreground" />
                        </CardHeader>
                        <CardContent>
                            <div className="text-2xl font-bold">{user.bookmarks.length}</div>
                            <p className="text-xs text-muted-foreground">Posts saved</p>
                        </CardContent>
                    </Card>
                </div>

                {/* Tabs */}
                <Tabs defaultValue="comments" className="w-full">
                    <TabsList className="grid w-full grid-cols-2">
                        <TabsTrigger value="comments">Comments</TabsTrigger>
                        <TabsTrigger value="bookmarks">Bookmarks</TabsTrigger>
                    </TabsList>

                    {/* Comments Tab */}
                    <TabsContent value="comments" className="mt-6">
                        {validComments.length === 0 ? (
                            <Card>
                                <CardContent className="text-center py-12">
                                    <MessageCircle className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                                    <p className="text-muted-foreground">No comments yet</p>
                                </CardContent>
                            </Card>
                        ) : (
                            <div className="space-y-4">
                                {validComments.map((comment) => (
                                    <Card key={comment.id}>
                                        <CardHeader>
                                            <div className="flex items-start justify-between">
                                                <div className="flex-1">
                                                    <CardTitle className="text-base mb-2">
                                                        <Link
                                                            href={`/blog/${comment.postSlug}`}
                                                            className="hover:underline"
                                                        >
                                                            {comment.post?.title}
                                                        </Link>
                                                    </CardTitle>
                                                    <CardDescription>
                                                        {formatDistanceToNow(new Date(comment.createdAt), {
                                                            addSuffix: true,
                                                        })}
                                                    </CardDescription>
                                                </div>
                                                <Badge variant="outline">{comment.post?.category}</Badge>
                                            </div>
                                        </CardHeader>
                                        <CardContent>
                                            <p className="text-sm whitespace-pre-wrap">{comment.content}</p>
                                        </CardContent>
                                    </Card>
                                ))}
                            </div>
                        )}
                    </TabsContent>

                    {/* Bookmarks Tab */}
                    <TabsContent value="bookmarks" className="mt-6">
                        {validBookmarks.length === 0 ? (
                            <Card>
                                <CardContent className="text-center py-12">
                                    <Bookmark className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
                                    <p className="text-muted-foreground">No bookmarks yet</p>
                                </CardContent>
                            </Card>
                        ) : (
                            <div className="grid gap-4 md:grid-cols-2">
                                {validBookmarks.map((bookmark) => (
                                    <Link key={bookmark.id} href={`/blog/${bookmark.postSlug}`}>
                                        <Card className="h-full hover:shadow-lg transition-shadow">
                                            <CardHeader>
                                                <Badge className="w-fit mb-2">{bookmark.post?.category}</Badge>
                                                <CardTitle className="line-clamp-2">
                                                    {bookmark.post?.title}
                                                </CardTitle>
                                                <CardDescription className="line-clamp-2">
                                                    {bookmark.post?.excerpt}
                                                </CardDescription>
                                            </CardHeader>
                                            <CardContent>
                                                <p className="text-xs text-muted-foreground">
                                                    Saved{" "}
                                                    {formatDistanceToNow(new Date(bookmark.createdAt), {
                                                        addSuffix: true,
                                                    })}
                                                </p>
                                            </CardContent>
                                        </Card>
                                    </Link>
                                ))}
                            </div>
                        )}
                    </TabsContent>
                </Tabs>
            </div>
        </div>
    );
}

"use client";

import { useState } from "react";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeHighlight from "rehype-highlight";
import { Eye, Code } from "lucide-react";
import "highlight.js/styles/github-dark.css";

interface MarkdownEditorProps {
    value: string;
    onChange: (value: string) => void;
    placeholder?: string;
}

export function MarkdownEditor({ value, onChange, placeholder }: MarkdownEditorProps) {
    const [activeTab, setActiveTab] = useState<"write" | "preview">("write");

    return (
        <Card>
            <CardHeader>
                <div className="flex items-center justify-between">
                    <CardTitle>Content *</CardTitle>
                    <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "write" | "preview")}>
                        <TabsList>
                            <TabsTrigger value="write" className="gap-2">
                                <Code className="h-4 w-4" />
                                Write
                            </TabsTrigger>
                            <TabsTrigger value="preview" className="gap-2">
                                <Eye className="h-4 w-4" />
                                Preview
                            </TabsTrigger>
                        </TabsList>
                    </Tabs>
                </div>
            </CardHeader>
            <CardContent>
                {activeTab === "write" ? (
                    <div className="space-y-2">
                        <Textarea
                            value={value}
                            onChange={(e) => onChange(e.target.value)}
                            placeholder={placeholder || "Write your content in Markdown..."}
                            rows={20}
                            className="font-mono text-sm"
                        />
                        <div className="text-xs text-muted-foreground space-y-1">
                            <p className="font-semibold">Markdown Tips:</p>
                            <div className="grid grid-cols-2 gap-2">
                                <code># Heading 1</code>
                                <code>## Heading 2</code>
                                <code>**bold**</code>
                                <code>*italic*</code>
                                <code>`code`</code>
                                <code>```language code block```</code>
                                <code>[link](url)</code>
                                <code>![image](url)</code>
                            </div>
                        </div>
                    </div>
                ) : (
                    <div className="prose prose-sm max-w-none dark:prose-invert min-h-[500px] p-4 border rounded-md bg-secondary/5">
                        <ReactMarkdown
                            remarkPlugins={[remarkGfm]}
                            rehypePlugins={[rehypeHighlight]}
                            components={{
                                code({ node, className, children, ...props }: any) {
                                    const match = /language-(\w+)/.exec(className || "");
                                    const inline = !node?.position;
                                    return !inline && match ? (
                                        <pre className={className}>
                                            <code className={className} {...props}>
                                                {children}
                                            </code>
                                        </pre>
                                    ) : (
                                        <code className={className} {...props}>
                                            {children}
                                        </code>
                                    );
                                },
                            }}
                        >
                            {value || "*No content yet. Switch to Write tab to start writing.*"}
                        </ReactMarkdown>
                    </div>
                )}
            </CardContent>
        </Card>
    );
}

