"use client";

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { calculateSEOScore } from "@/lib/post-helpers";
import { useState, useEffect } from "react";
import { AlertCircle, CheckCircle2 } from "lucide-react";

interface SEOPanelProps {
    title: string;
    metaTitle: string;
    metaDescription: string;
    focusKeyword: string;
    content: string;
    onMetaTitleChange: (value: string) => void;
    onMetaDescriptionChange: (value: string) => void;
    onFocusKeywordChange: (value: string) => void;
}

export function SEOPanel({
    title,
    metaTitle,
    metaDescription,
    focusKeyword,
    content,
    onMetaTitleChange,
    onMetaDescriptionChange,
    onFocusKeywordChange,
}: SEOPanelProps) {
    const [seoScore, setSeoScore] = useState({ score: 0, suggestions: [] as string[] });

    useEffect(() => {
        const headings = content.match(/^#{1,6}\s+.+$/gm) || [];
        const score = calculateSEOScore({
            title: metaTitle || title,
            metaDescription,
            focusKeyword,
            content,
            headings,
        });
        setSeoScore(score);
    }, [title, metaTitle, metaDescription, focusKeyword, content]);

    const getScoreColor = (score: number) => {
        if (score >= 80) return "text-green-600";
        if (score >= 60) return "text-yellow-600";
        return "text-red-600";
    };

    const getScoreBadge = (score: number) => {
        if (score >= 80) return "Good";
        if (score >= 60) return "Needs Work";
        return "Poor";
    };

    return (
        <div className="space-y-6">
            {/* SEO Score */}
            <Card>
                <CardHeader>
                    <CardTitle className="flex items-center justify-between">
                        <span>SEO Score</span>
                        <div className="flex items-center gap-2">
                            <span className={`text-3xl font-bold ${getScoreColor(seoScore.score)}`}>
                                {seoScore.score}
                            </span>
                            <Badge variant={seoScore.score >= 80 ? "default" : "secondary"}>
                                {getScoreBadge(seoScore.score)}
                            </Badge>
                        </div>
                    </CardTitle>
                    <CardDescription>
                        Optimize your content for search engines
                    </CardDescription>
                </CardHeader>
                {seoScore.suggestions.length > 0 && (
                    <CardContent>
                        <div className="space-y-2">
                            {seoScore.suggestions.map((suggestion, index) => (
                                <div key={index} className="flex items-start gap-2 text-sm">
                                    <AlertCircle className="h-4 w-4 text-yellow-600 mt-0.5" />
                                    <span>{suggestion}</span>
                                </div>
                            ))}
                        </div>
                    </CardContent>
                )}
            </Card>

            {/* Meta Title */}
            <div className="space-y-2">
                <Label htmlFor="metaTitle">
                    Meta Title {metaTitle && `(${metaTitle.length}/60)`}
                </Label>
                <Input
                    id="metaTitle"
                    value={metaTitle}
                    onChange={(e) => onMetaTitleChange(e.target.value)}
                    placeholder={title || "Enter meta title..."}
                    maxLength={60}
                />
                <p className="text-xs text-muted-foreground">
                    Optimal length: 50-60 characters. Leave empty to use post title.
                </p>
            </div>

            {/* Meta Description */}
            <div className="space-y-2">
                <Label htmlFor="metaDescription">
                    Meta Description {metaDescription && `(${metaDescription.length}/160)`}
                </Label>
                <Textarea
                    id="metaDescription"
                    value={metaDescription}
                    onChange={(e) => onMetaDescriptionChange(e.target.value)}
                    placeholder="Enter a compelling description for search results..."
                    maxLength={160}
                    rows={3}
                />
                <p className="text-xs text-muted-foreground">
                    Optimal length: 150-160 characters
                </p>
            </div>

            {/* Focus Keyword */}
            <div className="space-y-2">
                <Label htmlFor="focusKeyword">Focus Keyword</Label>
                <Input
                    id="focusKeyword"
                    value={focusKeyword}
                    onChange={(e) => onFocusKeywordChange(e.target.value)}
                    placeholder="e.g., best smartphones 2025"
                />
                <p className="text-xs text-muted-foreground">
                    Main keyword you want to rank for
                </p>
            </div>

            {/* Google Preview */}
            <Card>
                <CardHeader>
                    <CardTitle className="text-base">Google Search Preview</CardTitle>
                </CardHeader>
                <CardContent>
                    <div className="space-y-1">
                        <div className="text-sm text-blue-600">
                            {metaTitle || title || "Your Post Title"}
                        </div>
                        <div className="text-xs text-green-700">
                            aanaa.blog › blog › {title.toLowerCase().replace(/\s+/g, '-')}
                        </div>
                        <div className="text-sm text-gray-600">
                            {metaDescription || "Your meta description will appear here..."}
                        </div>
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

"use client";

import { useState, useEffect } from "react";
import { useSession } from "next-auth/react";
import { Button } from "@/components/ui/button";
import { Bookmark, BookmarkCheck } from "lucide-react";

interface BookmarkButtonProps {
    postSlug: string;
}

export function BookmarkButton({ postSlug }: BookmarkButtonProps) {
    const { data: session } = useSession();
    const [isBookmarked, setIsBookmarked] = useState(false);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (session?.user) {
            checkBookmarkStatus();
        }
    }, [session, postSlug]);

    const checkBookmarkStatus = async () => {
        try {
            const response = await fetch("/api/bookmarks");
            const data = await response.json();
            const bookmarked = data.bookmarks?.some(
                (b: any) => b.postSlug === postSlug
            );
            setIsBookmarked(bookmarked);
        } catch (error) {
            console.error("Failed to check bookmark status:", error);
        }
    };

    const toggleBookmark = async () => {
        if (!session?.user) {
            window.location.href = "/login";
            return;
        }

        setLoading(true);
        try {
            if (isBookmarked) {
                // Remove bookmark
                const response = await fetch(`/api/bookmarks?postSlug=${postSlug}`, {
                    method: "DELETE",
                });
                if (response.ok) {
                    setIsBookmarked(false);
                }
            } else {
                // Add bookmark
                const response = await fetch("/api/bookmarks", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ postSlug }),
                });
                if (response.ok) {
                    setIsBookmarked(true);
                }
            }
        } catch (error) {
            console.error("Failed to toggle bookmark:", error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Button
            variant={isBookmarked ? "default" : "glass"}
            size="sm"
            onClick={toggleBookmark}
            disabled={loading}
            className="gap-2 apple-press"
        >
            {isBookmarked ? (
                <>
                    <BookmarkCheck className="h-4 w-4" />
                    Saved
                </>
            ) : (
                <>
                    <Bookmark className="h-4 w-4" />
                    Save
                </>
            )}
        </Button>
    );
}

"use client";

import { useEffect, useState } from "react";
import { cn } from "@/lib/utils";
import { ListOrdered } from "lucide-react";

interface TocItem {
    id: string;
    text: string;
    level: number;
}

export function TableOfContents() {
    const [headings, setHeadings] = useState<TocItem[]>([]);
    const [activeId, setActiveId] = useState<string>("");

    useEffect(() => {
        // Extract headings from the article
        const article = document.querySelector("article");
        if (!article) return;

        const headingElements = article.querySelectorAll("h2, h3");
        const items: TocItem[] = [];

        headingElements.forEach((heading, index) => {
            const id = heading.id || `heading-${index}`;
            if (!heading.id) {
                heading.id = id;
            }

            items.push({
                id,
                text: heading.textContent || "",
                level: parseInt(heading.tagName[1]),
            });
        });

        setHeadings(items);

        // Set up intersection observer for active heading
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach((entry) => {
                    if (entry.isIntersecting) {
                        setActiveId(entry.target.id);
                    }
                });
            },
            {
                rootMargin: "-100px 0px -80% 0px",
            }
        );

        headingElements.forEach((heading) => observer.observe(heading));

        return () => observer.disconnect();
    }, []);

    const scrollToHeading = (id: string) => {
        const element = document.getElementById(id);
        if (element) {
            const offset = 80; // Account for fixed header
            const elementPosition = element.getBoundingClientRect().top;
            const offsetPosition = elementPosition + window.pageYOffset - offset;

            window.scrollTo({
                top: offsetPosition,
                behavior: "smooth",
            });
        }
    };

    if (headings.length === 0) {
        return null;
    }

    return (
        <div className="hidden xl:block">
            <div className="sticky top-24 max-h-[calc(100vh-8rem)] overflow-y-auto glass-card p-5 rounded-2xl">
                <div className="flex items-center gap-2 mb-3.5 pb-2.5 border-b border-black/[0.05] dark:border-white/[0.08]">
                    <ListOrdered className="h-4 w-4 text-primary" />
                    <h4 className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">
                        On This Page
                    </h4>
                </div>
                <nav className="space-y-1">
                    {headings.map((heading) => (
                        <button
                            key={heading.id}
                            onClick={() => scrollToHeading(heading.id)}
                            className={cn(
                                "block w-full text-left text-xs leading-relaxed transition-all py-1 rounded-md",
                                heading.level === 3 && "pl-3 text-[11px]",
                                activeId === heading.id
                                    ? "text-primary font-semibold border-l-2 border-primary pl-2.5 bg-primary/5"
                                    : "text-muted-foreground hover:text-foreground border-l-2 border-transparent pl-2.5"
                            )}
                        >
                            {heading.text}
                        </button>
                    ))}
                </nav>
            </div>
        </div>
    );
}

"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { useSession } from "next-auth/react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { MessageCircle, Trash2, Reply } from "lucide-react";
import Link from "next/link";
import { formatDistanceToNow } from "date-fns";

interface Comment {
    id: string;
    content: string;
    createdAt: string;
    user: {
        name: string | null;
        email: string | null;
        image: string | null;
    };
    replies?: Comment[];
}

interface CommentsSectionProps {
    postSlug: string;
}

export function CommentsSection({ postSlug }: CommentsSectionProps) {
    const { data: session } = useSession();
    const [comments, setComments] = useState<Comment[]>([]);
    const [newComment, setNewComment] = useState("");
    const [replyTo, setReplyTo] = useState<string | null>(null);
    const [replyContent, setReplyContent] = useState("");
    const [error, setError] = useState("");
    const inFlight = useRef(false);
    const [loading, setLoading] = useState(false);
    const [fetchLoading, setFetchLoading] = useState(true);

    useEffect(() => {
        fetchComments();
    }, [postSlug]);

    const fetchComments = async () => {
        try {
            const response = await fetch(`/api/comments?postSlug=${postSlug}`);
            if (!response.ok) throw new Error("Failed to load");
            const data = await response.json();
            setComments(data.comments || []);
        } catch (error) {
            setError("Comments could not load. Please reload to try again.");
        } finally {
            setFetchLoading(false);
        }
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (inFlight.current || !session) return;
        if (!newComment.trim() || newComment.length > 5000) { setError("Enter a comment between 1 and 5,000 characters."); return; }

        inFlight.current = true; setError(""); setLoading(true);
        try {
            const response = await fetch("/api/comments", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    postSlug,
                    content: newComment,
                }),
            });

            if (response.ok) {
                setNewComment("");
                fetchComments();
            } else { setError("Couldn’t save the change. Please try again."); }
        } catch (error) {
            setError("Couldn’t connect. Your comment has been kept.");
        } finally {
            inFlight.current = false; setLoading(false);
        }
    };

    const handleDelete = async (commentId: string) => {
        if (!confirm("Are you sure you want to delete this comment?")) return;

        try {
            const response = await fetch(`/api/comments/${commentId}`, {
                method: "DELETE",
            });

            if (response.ok) {
                fetchComments();
            } else { setError("Couldn’t save the change. Please try again."); }
        } catch (error) {
            setError("Couldn’t delete the comment. Try again.");
        }
    };

    const handleReply = async (parentId: string) => {
        if (inFlight.current || !session) return;
        if (!replyContent.trim() || replyContent.length > 5000) { setError("Enter a reply between 1 and 5,000 characters."); return; }

        inFlight.current = true; setError(""); setLoading(true);
        try {
            const response = await fetch("/api/comments", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({
                    postSlug,
                    content: replyContent,
                    parentId,
                }),
            });

            if (response.ok) {
                setReplyContent("");
                setReplyTo(null);
                fetchComments();
            } else { setError("Couldn’t save the change. Please try again."); }
        } catch (error) {
            setError("Couldn’t connect. Your reply has been kept.");
        } finally {
            inFlight.current = false; setLoading(false);
        }
    };

    const CommentItem = ({ comment, isReply = false }: { comment: Comment; isReply?: boolean }) => (
        <div className={`${isReply ? "ml-8 md:ml-12 mt-4" : "mt-6"}`}>
            <div className="flex gap-3">
                <Avatar className="h-9 w-9 border border-black/[0.06] dark:border-white/[0.08]">
                    <AvatarImage src={comment.user.image || undefined} alt="" />
                    <AvatarFallback className="text-xs bg-primary/10 text-primary font-semibold">
                        {comment.user.name?.charAt(0) || comment.user.email?.charAt(0) || "U"}
                    </AvatarFallback>
                </Avatar>
                <div className="flex-1">
                    <div className="glass-card rounded-2xl p-4 shadow-xs">
                        <div className="flex items-center justify-between mb-2">
                            <div>
                                <span className="font-semibold text-xs text-foreground">{comment.user.name || "Anonymous"}</span>
                                <span className="text-[11px] text-muted-foreground ml-2">
                                    {formatDistanceToNow(new Date(comment.createdAt), { addSuffix: true })}
                                </span>
                            </div>
                            {session && (
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    aria-label="Delete comment"
                                    onClick={() => handleDelete(comment.id)}
                                    className="h-11 w-11 p-0 rounded-full hover:bg-red-500/10 hover:text-red-500 transition-colors"
                                >
                                    <Trash2 className="h-3.5 w-3.5" />
                                </Button>
                            )}
                        </div>
                        <p className="text-xs leading-relaxed text-foreground/90 whitespace-pre-wrap">{comment.content}</p>
                    </div>
                    {!isReply && session && (
                        <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => setReplyTo(replyTo === comment.id ? null : comment.id)}
                            className="mt-1.5 h-7 px-2.5 text-xs text-muted-foreground hover:text-foreground rounded-full"
                        >
                            <Reply className="h-3 w-3 mr-1.5 text-primary" />
                            Reply
                        </Button>
                    )}
                    {replyTo === comment.id && (
                        <div className="mt-3 space-y-2">
                            <Textarea
                                aria-label="Your reply" maxLength={5000} aria-describedby="comments-feedback"
                                value={replyContent}
                                onChange={(e) => setReplyContent(e.target.value)}
                                placeholder="Write a reply..."
                                className="min-h-[80px] glass-input rounded-2xl text-xs resize-none p-3"
                            />
                            <div className="flex gap-2">
                                <Button
                                    onClick={() => handleReply(comment.id)}
                                    disabled={loading || !replyContent.trim()}
                                    size="sm"
                                    className="rounded-full text-xs px-4 apple-press"
                                >
                                    {loading ? "Posting..." : "Post Reply"}
                                </Button>
                                <Button
                                    variant="glass"
                                    size="sm"
                                    onClick={() => {
                                        setReplyTo(null);
                                        setReplyContent("");
                                    }}
                                    className="rounded-full text-xs px-4 apple-press"
                                >
                                    Cancel
                                </Button>
                            </div>
                        </div>
                    )}
                    {comment.replies && comment.replies.length > 0 && (
                        <div className="mt-3">
                            {comment.replies.map((reply) => (
                                <CommentItem key={reply.id} comment={reply} isReply />
                            ))}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );

    return (
        <div className="mt-16 pt-16 border-t border-black/[0.06] dark:border-white/[0.08]">
            <div className="flex items-center gap-2 mb-8">
                <div className="w-8 h-8 rounded-xl bg-primary/10 flex items-center justify-center text-primary">
                    <MessageCircle className="h-4 w-4" />
                </div>
                <h2 className="text-xl sm:text-2xl font-bold tracking-tight text-foreground">
                    Comments ({comments.length})
                </h2>
            </div>

            <p id="comments-feedback" role={error ? "alert" : "status"} className="text-sm mb-4">{error || (loading ? "Saving…" : "")}</p>
            {session ? (
                <form onSubmit={handleSubmit} aria-busy={loading} className="mb-10">
                    <Textarea
                        aria-label="Your comment" maxLength={5000} aria-describedby="comments-feedback"
                        value={newComment}
                        onChange={(e) => setNewComment(e.target.value)}
                        placeholder="Share your thoughts..."
                        className="min-h-[110px] glass-input rounded-2xl text-xs leading-relaxed p-4 resize-none"
                    />
                    <Button
                        type="submit"
                        disabled={loading || !newComment.trim()}
                        className="mt-3 rounded-full px-5 text-xs apple-press shadow-sm"
                    >
                        {loading ? "Posting..." : "Post Comment"}
                    </Button>
                </form>
            ) : (
                <div className="glass-card rounded-3xl p-6 sm:p-8 mb-10 text-center">
                    <p className="text-sm text-muted-foreground mb-4">
                        Please sign in to join the conversation and leave a comment
                    </p>
                    <Button asChild className="rounded-full px-6 apple-press">
                        <Link href="/login">Sign In</Link>
                    </Button>
                </div>
            )}

            {fetchLoading ? (
                <p className="text-xs text-muted-foreground text-center py-6">Loading comments...</p>
            ) : comments.length === 0 ? (
                <div className="glass-subtle rounded-2xl p-8 text-center text-muted-foreground text-xs">
                    No comments yet. Be the first to share your thoughts!
                </div>
            ) : (
                <div className="space-y-2">
                    {comments.map((comment) => (
                        <CommentItem key={comment.id} comment={comment} />
                    ))}
                </div>
            )}
        </div>
    );
}

"use client";

import * as React from "react";
import Link from "next/link";
import { useTheme } from "next-themes";
import { useSession, signOut } from "next-auth/react";
import { Search, Sun, Moon, Menu, X, User, LogOut, BookmarkIcon } from "lucide-react";
import { BrandLogo } from "@/components/brand-logo";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { SearchWithSuggestions } from "@/components/search/search-with-suggestions";

export function Header() {
    const { setTheme, theme } = useTheme();
    const { data: session, status } = useSession();
    const [isMenuOpen, setIsMenuOpen] = React.useState(false);
    const [isUserMenuOpen, setIsUserMenuOpen] = React.useState(false);
    const [scrolled, setScrolled] = React.useState(false);

    React.useEffect(() => {
        const handleScroll = () => {
            setScrolled(window.scrollY > 10);
        };
        window.addEventListener("scroll", handleScroll);
        return () => window.removeEventListener("scroll", handleScroll);
    }, []);

    return (
        <header onKeyDown={(event) => { if (event.key === "Escape") { setIsMenuOpen(false); setIsUserMenuOpen(false); } }}
            className={`sticky top-0 z-50 w-full transition-all duration-300 border-b ${scrolled
                ? "bg-white/75 dark:bg-black/75 backdrop-blur-2xl backdrop-saturate-200 border-black/[0.06] dark:border-white/[0.08] shadow-[0_4px_24px_-4px_rgba(0,0,0,0.05)] dark:shadow-[0_4px_24px_-4px_rgba(0,0,0,0.5)]"
                : "bg-white/45 dark:bg-black/40 backdrop-blur-xl border-transparent"
