                        { href: "/category/phones", label: "Phones" },
                        { href: "/category/gadgets", label: "Gadgets" },
                        { href: "/category/ai-tools", label: "AI Tools" },
                        { href: "/category/guides", label: "Guides" },
                        { href: "/category/news", label: "News" },
