                                            <div className="py-1">
                                                <Link
                                                    href={`/profile/${session.user.id}`}
                                                    className="flex items-center gap-3 px-4 py-2 text-sm text-foreground hover:bg-black/[0.04] dark:hover:bg-white/[0.06] transition-colors"
